window.QB_PAPERS=window.QB_PAPERS||{};window.QB_PAPERS["p7e519edba8"]={"id":"p7e519edba8","name":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）","year":2023,"region":"浙江","count":72,"types":{"新思想":1,"时事政治":1,"逻辑填空":11,"语句表达":5,"片段阅读":14,"图形推理":11,"定义判断":10,"类比推理":11,"逻辑判断":8},"modules":["政治理论","言语理解与表达","判断推理"],"questions":[{"qid":"5430247","no":1,"type":"新思想","module":"政治理论","stem":"<p>2022年10月22日，中国共产党第二十次全国代表大会审议并一致通过十九届中央委员会提出的《中国共产党章程（修正案）》。下列关于这一修正案的表述，正确的有：<br>①把充分发挥人才作为第一资源的作用写入党章<br>②把党是最高政治领导力量，坚持和加强党的全面领导写入党章<br>③把党的十九大以来习近平新时代中国特色社会主义思想新发展写入党章<br>④把坚持政治建军、改革强军、科技强军、人才强军、依法治军，把人民军队建设成为世界一流军队写入党章</p>","options":[{"k":"A","t":"1项"},{"k":"B","t":"2项"},{"k":"C","t":"3项"},{"k":"D","t":"4项"}],"answer":"D","multi":false,"explanation":"<p>本题考查政治常识。<br>①正确，大会认为，党的二十大提出以中国式现代化全面推进中华民族伟大复兴，并将此确定为新时代新征程中国共产党的中心任务······大会同意把上述内容写入党章，同意把逐步实现全体人民共同富裕，把握新发展阶段，贯彻创新、协调、绿色、开放、共享的新发展理念，加快构建以国内大循环为主体、国内国际双循环相互促进的新发展格局，推动高质量发展，充分发挥人才作为第一资源的作用，促进国民经济更高质量、更有效率、更加公平、更可持续、更为安全发展等内容写入党章。<br>②正确，大会认为，中国共产党是领导我们事业的核心力量，党的领导是实现中华民族伟大复兴的根本保证。大会同意把党是最高政治领导力量，坚持和加强党的全面领导等内容写入党章。这有利于充分发挥党总揽全局、协调各方的领导核心作用，把党的领导落实到党和国家事业各领域各方面各环节。<br>③正确，大会一致同意，把党的十九大以来习近平新时代中国特色社会主义思想新发展写入党章，以更好反映以习近平同志为核心的党中央推进党的理论创新、实践创新、制度创新成果。大会要求全党深刻领悟“两个确立”的决定性意义，全面贯彻习近平新时代中国特色社会主义思想，把这一思想贯彻落实到党和国家工作各方面全过程。<br>④正确，大会认为，党的十九大以来，习近平同志就加强国防和军队建设、统战工作、外交工作提出一系列新理念新思想新战略。大会同意，把坚持政治建军、改革强军、科技强军、人才强军、依法治军，把人民军队建设成为世界一流军队；全面准确、坚定不移贯彻“一个国家、两种制度”的方针，坚决反对和遏制“台独”；弘扬和平、发展、公平、正义、民主、自由的全人类共同价值，推动建设持久和平、普遍安全、共同繁荣、开放包容、清洁美丽的世界等内容写入党章。<br>综上所述，正确的有①②③④，共4项。<br>故正确答案为D。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"政治理论"},"idx":0,"pid":"p7e519edba8"},{"qid":"5430248","no":2,"type":"时事政治","module":"政治理论","stem":"<p>习近平总书记在党的二十大报告中指出，十年来，我们经历了对党和人民事业具有重大现实意义和深远历史意义的三件大事。下列不属于“三件大事”的是：</p>","options":[{"k":"A","t":"迎来中国共产党成立一百周年"},{"k":"B","t":"中国特色社会主义进入新时代"},{"k":"C","t":"谱写马克思主义中国化时代化新篇章"},{"k":"D","t":"完成脱贫攻坚、全面建成小康社会的历史任务，实现第一个百年奋斗目标"}],"answer":"C","multi":false,"explanation":"<p>本题考查政治常识。<br>A、B、D三项正确，C项错误，党的二十大报告中指出：“同志们！十八大召开至今已经十年了。十年来，我们经历了对党和人民事业具有重大现实意义和深远历史意义的三件大事：一是迎来中国共产党成立一百周年，二是中国特色社会主义进入新时代，三是完成脱贫攻坚、全面建成小康社会的历史任务，实现第一个百年奋斗目标。这是中国共产党和中国人民团结奋斗赢得的历史性胜利，是彪炳中华民族发展史册的历史性胜利，也是对世界具有深远影响的历史性胜利。”<br>本题为选非题，故正确答案为C。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"政治理论"},"idx":1,"pid":"p7e519edba8"},{"qid":"5430310","no":1,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>城市形象不是<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的，它会随着一座城市的发展需要而产生相应的变化，因此，对于城市形象的研究也应当<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"千篇一律 兼收并蓄"},{"k":"B","t":"墨守陈规 求同存异"},{"k":"C","t":"因循守旧 革故鼎新"},{"k":"D","t":"一成不变 与时俱进"}],"answer":"D","multi":false,"explanation":"<p>本题可从第二空入手，根据“因此”可知，横线处应与“随着一座城市的发展需要而产生相应的变化”对应，体现随着事物的发展而变化之意。D项“与时俱进”指随着时代的发展而不断发展、前进，与文意相符，保留。A项“兼收并蓄”指把内容不同、性质不同的东西都吸收进来，B项“求同存异”指找出共同点，保留不同点，C项“革故鼎新”指去掉旧的，建立新的，均无法体现随着事物的发展而变化之意，排除。<br>第一空，代入验证，根据“随着一座城市的发展需要而产生相应的变化”，结合横线前的否定词可知，横线处应体现不随事物发展而变化之意。D项“一成不变”指一经形成，不再改变，与文意相符，当选。<br>故正确答案为D。<br>【文段出处】《基于扎根理论的澳门城市形象定位研究》</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"言语理解与表达"},"idx":2,"pid":"p7e519edba8"},{"qid":"5430312","no":2,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>《走出非洲》是二十世纪最伟大的英语文学作品之一。这部在散文、小说、自传间自由<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的作品，以1914至1931年间，作者在肯尼亚恩贡山麓经营咖啡农场的经历为背景，<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>地将众多的人、景、物熔于一炉，既有忠实而富文学性的观察与描摹，也始终贯穿着对自身、对人性的思考。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"切换 匠心独运"},{"k":"B","t":"穿插 深入浅出"},{"k":"C","t":"变幻 举重若轻"},{"k":"D","t":"出入 不动声色"}],"answer":"A","multi":false,"explanation":"<p>第一空，搭配“作品”，且根据前文“这部在散文、小说、自传间自由······”可知，横线处应表达这部作品具备散文、小说、自传三种文体的风格特点。A项“切换”指影视片等从某一镜头或画面迅速转换到另一镜头或画面，也泛指转换，符合文意，保留。B项“穿插”指小说或戏曲中，插入一些次要情节，以衬托主题，C项“变幻”指不规则的改变，常用于“风云变幻”“变幻莫测”等，D项“出入”指出去和进来，均无法体现出这部作品具有三种文体的风格，与文意不符，排除。<br>第二空，代入验证，对应横线前后语境，根据作者结合自身经历，将众多的人、景、物相融合，既有观察与描摹，也贯穿着对自身、对人性的思考可知，作者在写作时运用了一些创造性的手法，倾注了一些心思，A项“匠心独运”指在文学、艺术等方面独创性地运用巧妙的心思，符合文意，当选。<br>故正确答案为A。<br>【文段出处】《海明威读过的“最优秀的关于非洲的书”，出自这位传奇女性之手》</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"言语理解与表达"},"idx":3,"pid":"p7e519edba8"},{"qid":"5430473","no":3,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>有的地方搞森林城市创建不计成本，选树种不考虑当地环境气候，一味<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，大搞南方草原风光、中部沿海风情的反气候移植。这种贪图表面光鲜、<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>生态效益、忽视经济效益和社会效益的做法，无疑背离了森林城市创建的初心。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"生搬硬套 无视"},{"k":"B","t":"标新立异 罔顾"},{"k":"C","t":"好大喜功 弱化"},{"k":"D","t":"贪大求全 漠视"}],"answer":"B","multi":false,"explanation":"<p>第一空，根据后文“反气候移植”以及“这种贪图表面光鲜”可知，横线处需体现一种外表美丽、新鲜特别的做法，B项“标新立异”指提出新奇的见解、主张，表示与一般不同，也指故意提出新奇的见解，表示自己与众不同，符合文意，保留。A项“生搬硬套”指不顾实际情况，机械地运用别人的经验，照抄别人的办法，文段中没有出现其他森林城市创建的经验用以借鉴，而是要进行不符合当地的新的气候移植，与文意不符，排除；C项“好大喜功”指不管条件是否许可，一心想做大事立大功，文段侧重强调不考虑当地环境气候进行反气候移植，并非“立大功”，排除；D项“贪大求全”指过分地贪图规模大而全面，文段并未体现“求全”的意思，排除。<br>第二空，代入验证，搭配“生态效益”，且与后文“忽视经济效益和社会效益”构成并列，B项“罔顾”指不顾及、没有顾及，符合文意，当选。<br>故正确答案为B。<br>【文段出处】经济日报《防止森林城市建设走样》</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"言语理解与表达"},"idx":4,"pid":"p7e519edba8"},{"qid":"5430315","no":4,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>有些教育者讲授思政课之所以效果不佳，一个重要的原因在于讲授的内容流于表面，<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，往往是从书本到书本，从理论到理论，致使授课看似在说理，实则缺乏理论深度与厚度，难以让人真正<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"舍本逐末 接受"},{"k":"B","t":"走马观花 理解"},{"k":"C","t":"浅尝辄止 信服"},{"k":"D","t":"缘木求鱼 认可"}],"answer":"C","multi":false,"explanation":"<p>第一空，由逗号引导近义并列，横线处应与“流于表面”表意接近。“流于表面”指停留在表面上，只在表面上做文章，而没有实际的内容。C项“浅尝辄止”指稍稍尝试一下就停止，比喻做事不肯下功夫深入钻研，能够体现停留在表面上之意，保留。A项“舍本逐末”指舍弃事物的根本的、主要的部分，而去追求细枝末节，文段并未体现本末之分，排除；B项“走马观花”指粗略地观察事物，侧重体现观察得不仔细，而文段要表达对于讲授的内容研究和理解过于肤浅，排除；D项“缘木求鱼”比喻方向、办法不对，一定达不到目的，不能体现停留在表面上之意，排除。<br>第二空，代入验证，根据“看似在说理，实则缺乏理论深度与厚度”可知，横线处应表达缺乏深度、厚度的理论难以让人接受、相信之意。C项“信服”指相信并佩服，与文意相符，当选。<br>故正确答案为C。<br>【文段出处】南方网《新时代思政课讲道理重在“深”“透”“活”》</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"言语理解与表达"},"idx":5,"pid":"p7e519edba8"},{"qid":"5430319","no":5,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>骈文的特点是追求形式美：对偶、声律、用典、藻饰。魏晋时期，这种刻意追求文学形式美的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，一方面促进了文学独立品格的建立，另一方面又造成了形式上的僵化和内容上的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"导向 苍白"},{"k":"B","t":"手法 单一"},{"k":"C","t":"潮流 呆板"},{"k":"D","t":"风尚 空洞"}],"answer":"D","multi":false,"explanation":"<p>本题可从第二空入手，横线处形容“刻意追求形式美”可能会对内容产生的消极影响，即过分注重形式美而忽略了内容，故横线处表达文学作品缺乏实质性内容之意，A项“苍白”形容没有旺盛的生命力，D项“空洞”指空虚而无内涵，缺乏实际内容，均符合文意，保留。B项“单一”指只有一种类型的，无法体现出对内容不看重导致的结果，排除；C项“呆板”意思是死板、不灵活，侧重不够灵活，而非缺乏实质内容，与文意不符，排除。<br>第一空，“刻意追求文学形式美”是一种文学创作的倾向、习惯，D项“风尚”指流行的风气和习惯，语义恰当，且刻意追求文学形式美形成一种风尚之后，衔接后文对文学产生的重大影响更为准确，当选。A项“导向”指引导的方向，文段并无引导之意，与文意不符，排除。<br>故正确答案为D。<br>【文段出处】《“五四”时期散文的发展及其特点》</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"言语理解与表达"},"idx":6,"pid":"p7e519edba8"},{"qid":"5430325","no":6,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>电影技术的运用，逐渐由“炫目”向为视听表现和角色叙事服务转变。大量高质量特效的运用，使不少国产电影的视觉<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>达到世界顶尖水平。而动作捕捉技术和人工智能深度学习技术的应用，直接<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>了电影的叙事能力，使电影的艺术表达更为生动和丰富。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"体验 强化"},{"k":"B","t":"呈现 提升"},{"k":"C","t":"冲击 拓展"},{"k":"D","t":"享受 升华"}],"answer":"B","multi":false,"explanation":"<p>第一空，搭配“国产电影”，横线处要体现高质量特效的运用给国产电影带来的视觉作用。B项“呈现”指显现、展示出，C项“冲击”指冲撞、碰击，均可体现给国产电影带来的视觉作用，符合文意，保留。A项“体验”指在实践中认识事物、亲身经历，D项“享受”指物质上或精神上得到满足，均常与“人”搭配，与“国产电影”搭配不当，排除。<br>第二空，搭配“叙事能力”，且根据后文“使电影的艺术表达更为生动和丰富”可知，横线处要体现“动作捕捉技术和人工智能深度学习技术的应用”对“电影的叙事能力”的促进作用。B项“提升”指提高，“提升能力”为惯用搭配，符合文意，当选。C项“拓展”指开拓、扩展，与“叙事能力”搭配不当，排除。<br>故正确答案为B。<br>【文段出处】《技术为电影艺术拓展新空间（科技赋能艺术）》</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"言语理解与表达"},"idx":7,"pid":"p7e519edba8"},{"qid":"5430332","no":7,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>探索浩瀚宇宙，是中华民族数千年来<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的追求。中国航天承载了一个大国的斑斓梦想，也<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>了新时代中国人的骄傲与情怀。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"矢志不渝 寄寓"},{"k":"B","t":"志在必得 铭刻"},{"k":"C","t":"亘古不变 映射"},{"k":"D","t":"孜孜不倦 彰显"}],"answer":"A","multi":false,"explanation":"<p>第一空，根据“中华民族数千年来”可知，横线处所填成语应体现坚持了很长时间之意。A项“矢志不渝”指立志不会改变，表示永远不变心，C项“亘古不变”指从古到今，没有变化，D项“孜孜不倦”指工作或学习勤奋刻苦不知疲倦，形容勤勉不懈怠的一种状态，均符合文意，保留。B项“志在必得”指立志要得到或完成某种愿望，未能体现坚持了很长时间之意，排除。<br>第二空，由“也”和前后句的相同句式可知，横线处所填词语与“承载”构成并列，应体现背负、寄托之意。A项“寄寓”指依附，寄托，符合文意，当选。C项“映射”指反射反映，不能体现背负、寄托之意，排除；D项“彰显”指鲜明地显示，侧重于“将······显示出来”，不能体现背负、寄托之意，且横线前搭配“中国航天”，而“彰显”的主语多为成果、事迹等，横线后搭配“骄傲与情怀”，“骄傲”是一种内在的情绪状态，无需鲜明地显示出来，“彰显”与前后搭配均不恰当，排除。<br>故正确答案为A。<br>【文段出处】《中国航天，新任务新征程》</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"言语理解与表达"},"idx":8,"pid":"p7e519edba8"},{"qid":"5430334","no":8,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>不让“同款”为山寨货遮羞，平台<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。大数据时代，任何人均能通过“同款”“仿品”等关键词，轻易找到造假售假的商家，平台坐拥先进的后台系统、人力技术优势，自能对平台内经营者侵犯知识产权行为<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"责无旁贷 洞若观火"},{"k":"B","t":"当仁不让 义不容辞"},{"k":"C","t":"烂熟于心 如数家珍"},{"k":"D","t":"难辞其咎 了如指掌"}],"answer":"A","multi":false,"explanation":"<p>第一空，根据后文“平台坐拥先进的后台系统、人力技术优势，自能对平台内经营者侵犯知识产权行为”可知，横线处应体现平台要承担起责任之意。A项“责无旁贷”指自己应尽的责任，不能推卸给旁人，B项“当仁不让”原指以仁为任，无所谦让，后指遇到应该做的事就积极主动去做，不推让，均符合文意，保留。C项“烂熟于心”形容对某件事情或者事物的发展情况在心里记得很清楚，没有体现出应当承担起责任之意，排除；D项“难辞其咎”指难以推脱其过失，文段并非要找到有过失的主体，排除。<br>第二空，根据前文内容可知，横线处应体现平台对经营者侵犯知识产权行为掌握得很清楚之意，A项“洞若观火”形容观察事物非常清楚，好像看火一样，符合文意，当选。B项“义不容辞”指道义上不允许推辞，无法体现出掌握得清楚之意，排除。<br>故正确答案为A。<br>【文段出处】《人民财评：莫让“同款”成山寨货的遮羞布》</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"言语理解与表达"},"idx":9,"pid":"p7e519edba8"},{"qid":"5430261","no":9,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>治理直播行业乱象不是为了束缚主播发展，而是鼓励其<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>内容；加强规范不是行业的终点，而是<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>发生的新起点。贯彻《网络主播行为规范》相关要求，让政策自上而下落实落地，让行业自下而上加强规范，定能形成高效的治理体系，为直播行业健康发展<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"挖掘 变革 雪中送炭"},{"k":"B","t":"丰富 复苏 披荆斩棘"},{"k":"C","t":"深耕 蝶变 保驾护航"},{"k":"D","t":"聚焦 转机 添砖加瓦"}],"answer":"C","multi":false,"explanation":"<p>本题可从第三空入手，根据前文“让政策自上而下落实落地，让行业自下而上加强规范，定能形成高效的治理体系”可知，横线处应体现出政策落实为直播行业健康发展发挥了很大作用，C项“保驾护航”指保护某事物让其能正常发展，常用来搭配“政府”“政策”，符合文意，保留。A项“雪中送炭”比喻在别人急需的时候给以帮助，B项“披荆斩棘”比喻扫除前进中的困难和障碍，文段并未论述直播行业遭遇困难或需要帮助，均与文意不符，排除；D项“添砖加瓦”原来指建房屋时不断地添砖块加瓦片，后比喻做一些工作，尽一点力量，强调微小力量对整体的作用，文段体现的是政策的作用，且根据“定能形成高效的治理体系”可知，文段并非强调微小力量，与文意不符，排除。<br>第一空，代入验证，C项“深耕”原指将土地深层的土壤翻上来，浅层的土壤覆下去，现多用来形容对内容的深入打磨，置于文段表达主播对内容的“精耕细作”，符合文意，保留。<br>第二空，代入验证，C项“蝶变”指向更好或更完美的方面极大蜕变，对应文段“新起点”，符合文意，当选。<br>故正确答案为C。<br>【文段出处】《人民艺起评：疏堵结合 让网络主播更好逐梦前行》</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"言语理解与表达"},"idx":10,"pid":"p7e519edba8"},{"qid":"5430264","no":10,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>中华文化是一座浩瀚的思想库，里面有很多珍宝，但也不乏糟粕，不是所有的内容都可以复活于当代、贡献于世界。时代的变迁决定了我们不可能<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>保留传统文化的一切方面。中华文明有的内容可以超越时空，有的内容则已尘封；有的可以古为今用，有的则应<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"循规蹈矩 去粗取精"},{"k":"B","t":"如法炮制 弃若敝屣"},{"k":"C","t":"固步自封 漠然置之"},{"k":"D","t":"原封不动 束之高阁"}],"answer":"D","multi":false,"explanation":"<p>第一空，根据“中华文化······但也不乏糟粕，不是所有的内容都可以复活于当代、贡献于世界”“有的可以古为今用，有的则应······”可知，横线处强调传统文化中有珍宝，也有糟粕，不能完全按照原样去保留传统文化的一切方面。D项“原封不动”比喻保持原来的样子，一点不加变动，符合文意，保留。A项“循规蹈矩”原指遵守规矩，现多指拘泥于旧的准则，不敢稍做变通，侧重强调遵守规则、准则，B项“如法炮制”指依照成法炮制药剂，泛指照现成的方法办事，文段并无按照规则准则或现成方法保留传统文化的意思，与文段语境无关，排除；C项“固步自封”比喻安于现状，不求进步，与否定词连用则侧重强调要创新、要进步，而文段强调的是传统文化中好的方面要古为今用，糟粕的方面要舍弃，而非强调要创新、要进步，不符合文意，排除。<br>第二空，代入验证。“有的内容可以超越时空，有的内容则已尘封；有的可以古为今用，有的则应······”构成一一对应，“古为今用”对应“超越时空”，故横线处对应“已尘封”，强调对于传统文化中的糟粕，要尘封起来。D项“束之高阁”指扔在一边，不去用它或管它，符合文意，当选。<br>故正确答案为D。<br>【文段出处】光明日报《以更有活力的文明成就贡献世界》</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"言语理解与表达"},"idx":11,"pid":"p7e519edba8"},{"qid":"5430266","no":11,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>并非所有的阅读都是一场对抗，一次<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的对话。有谁未曾被一篇扣人心弦、<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的论述所折服，未曾<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>在他人的思维里，而又被一声电话铃声或其他干扰拽回现实？<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"唇枪舌剑 字字珠玑 沉醉"},{"k":"B","t":"雄辩高谈 丝丝入扣 迷醉"},{"k":"C","t":"舌战群儒 笔底生花 沉浸"},{"k":"D","t":"剑拔弩张 巧舌如簧 陶醉"}],"answer":"A","multi":false,"explanation":"<p>第一空，根据“一场······一次······”可知，横线处与“对抗”构成并列关系，应体现阅读中读者与作者对抗的状态。A项“唇枪舌剑”形容争辩激烈，言辞锋利，D项“剑拔弩张”形容形势紧张，一触即发，均与文意相符，保留。B项“雄辩高谈”形容一个人能言善辩，无法体现文段中双方“对抗”之意，排除；C项“舌战群儒”指同很多人辩论，并驳倒对方，文段中表达的是阅读中“读者与作者”之间的对抗，并无“同很多人辩论”之意，排除。<br>第二空，根据“、”可知，横线处与“扣人心弦”意思相近，且根据“折服”可知，横线处应体现论述很精彩之意。A项“字字珠玑”意为文章中遣词用字非常优美，与文意相符，保留。D项“巧舌如簧”意为舌头灵巧得就像乐器里的簧片一样，形容能说会道，善于狡辩，感情色彩偏消极，与文段感情色彩不符，排除。<br>第三空，代入验证，根据“而又被一声电话铃声或其他干扰拽回现实”可知，横线处应体被他人的思维所深深吸引之意。A项“沉醉”比喻为美好的事物所陶醉，与文意相符，当选。<br>故正确答案为A。<br>【文段出处】《静默》约翰·毕谷纳特</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"言语理解与表达"},"idx":12,"pid":"p7e519edba8"},{"qid":"5430268","no":12,"type":"语句表达","module":"言语理解与表达","stem":"<p>①建议从事童书出版的机构聘请心理学、教育学、出版学等相关领域专家共同把关，为儿童读物筑牢安全防线<br>②童书出版有必要设立严格门槛<br>③童书出版需要认定资质、配备专业编辑，目前在这方面尚有欠缺<br>④我国现有专业少儿出版社30多家，随着市场需求增长，少儿出版的队伍不断壮大<br>⑤童书正在从原来的专业出版变为大众出版<br>⑥目前全国583家出版社，参与少儿出版的已经超过550家<br>将以上6个句子重新排序，语序正确的一项是：</p>","options":[{"k":"A","t":"③②①④⑥⑤"},{"k":"B","t":"④⑥⑤②③①"},{"k":"C","t":"⑤④③⑥①②"},{"k":"D","t":"⑥②①④⑤③"}],"answer":"B","multi":false,"explanation":"<p>对比选项，确定首句，③句论述目前童书出版存在的问题，④句论述我国少儿出版的队伍不断壮大，⑤句论述童书从专业出版变为大众出版这一变化，⑥句论述目前全国参与少儿出版的出版社的具体数据，按照逻辑顺序，应先论述少儿出版的队伍不断壮大，再具体列数据说明，故④句应在⑥句之前，排除D项。<br>观察选项发现，与A、B两项的④⑥捆绑不同，C项为④③⑥，③句论述目前童书出版存在的问题，④⑥共同论述少儿出版的队伍不断壮大的话题，故③句不适合在④⑥中间，排除C项。<br>继续寻找线索，对比尾句，①句为对策表述，论述建议聘请各领域专家共同把关，为儿童读物筑牢安全防线，⑤句论述童书从专业出版变为大众出版的这一变化，不及①句的对策适合作为尾句，排除A项，B项当选。<br>故正确答案为B。<br>【文段出处】北青网《筑牢童书安全防线》</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"言语理解与表达"},"idx":13,"pid":"p7e519edba8"},{"qid":"5430271","no":13,"type":"语句表达","module":"言语理解与表达","stem":"<p>①城镇化意味着对人口自由发展需求的满足，本质上要服务于人民<br>②据统计，2010年到2020年十年间，全国农村总流出人口中跨省进城人口增加2657万人，省内进城人口增长近1.12亿人<br>③事实上，近年来“人口回流促进区域内城市发展，城市发展进一步吸引人口回流”的循环互动在各地不断上演<br>④人口往哪里流动，城镇化的方向就应当往哪里延伸，随着人口省内流动日益频繁，作为城乡融合的重要载体，县域的城镇化是大势所趋<br>⑤这表明，省内城市务工成为近年来人口流动的趋势<br>⑥近年来，人口流动呈现出“跨省区人口流动趋缓、近域化流动趋势加强”的新趋势<br>将以上6个句子重新排序，语序正确的一项是：</p>","options":[{"k":"A","t":"①②③④⑥⑤"},{"k":"B","t":"②⑥⑤③①④"},{"k":"C","t":"④③⑥①②⑤"},{"k":"D","t":"⑥②⑤③①④"}],"answer":"D","multi":false,"explanation":"<p>对比选项，判断首句。①句引出“城镇化”的话题，论述了城镇化的本质；②句详细论述了跨省进城与省内进城的增长人数；④句论述了随着人口省内流动日益频繁，县域的城镇化是大势所趋；⑥句通过“近年来”引出背景，论述了人口流动呈现“跨省区人口流动趋缓、近域化流动趋势加强”的新趋势。对比②句和⑥句，⑥句为当前背景，②句为对于背景的详细的数据论证，因此⑥句应在②句之前，排除A、B两项。再对比④句和⑥句，⑥句指出省内人口流动加强的新趋势，④句指出“随着人口省内流动日益频繁”，按照日常逻辑顺序，应该先说明人口流动加强的新趋势，再说人口省内流动日益频繁，因此⑥句应在④句之前，排除C项，D项当选。<br>故正确答案为D。<br>【文段出处】《人民财评：发挥县域为载体的城镇化发展优势》</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"言语理解与表达"},"idx":14,"pid":"p7e519edba8"},{"qid":"5430274","no":14,"type":"语句表达","module":"言语理解与表达","stem":"<p>①根本还在于建立能够保障教师待遇及权利、明晰教师职责的教师管理新体系<br>②禁止教师有偿兼职补课是重要的“师德红线”<br>③然而在现实中，却一直难以切实落地，每年各地仍会出现教师有偿兼职补课的师德问题<br>④如何破解这一难题<br>⑤不少教育管理者和学校管理者强调“发现一起，严惩一起”，但治标不治本<br>⑥如果不依法保障教师待遇，却要求教师履行更高的职责，师德建设就会沦为空泛的说教<br>将以上6个句子重新排序，语序正确的一项是：</p>","options":[{"k":"A","t":"②③④⑤①⑥"},{"k":"B","t":"②③⑤④⑥①"},{"k":"C","t":"④②③⑤①⑥"},{"k":"D","t":"④②⑤③⑥①"}],"answer":"A","multi":false,"explanation":"<p>对比选项，确定首句。②句引出“教师有偿兼职补课”这一话题，适合作为首句，保留A、B两项。④句出现指代词“这一难题”，指代不清，不适合作为首句，排除C、D两项。<br>继续观察发现，A、B两项的尾句不同。①句提出对策，即建立能够保障教师待遇及权利、明晰教师职责的教师管理新体系，⑥句通过反面论证的形式，进一步论证①句提出的对策，按照日常逻辑顺序，①句应在⑥句之前，故⑥句相较于①句更适合作为尾句，排除B项，A项当选。<br>故正确答案为A。<br>【文段出处】《光明时评：以专业化师德师风建设回应社会期待》</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"言语理解与表达"},"idx":15,"pid":"p7e519edba8"},{"qid":"5430276","no":15,"type":"片段阅读","module":"言语理解与表达","stem":"<p>在社会文化的变革中，如果要创新，就必须要有新的思维，必须突破原有的观念体系和知识框架，必须要对社会已经蔓延的“常识”进行反思和批判。这里的“常识”，指既定的思想框架和方法路径。尽管这种思想框架和方法路径可能是人类智慧和实践的一种积累，但是随着历史的发展，它很可能又变成了一种枷锁，限制和捆绑着人们的创造力。我们的反思、修正、突破和创新，都需要不断地去做各种各样的尝试。<br>这段文字意在强调：</p>","options":[{"k":"A","t":"“常识”容易让人墨守成规"},{"k":"B","t":"要创新就必须突破“常识”"},{"k":"C","t":"突破和创新需要大胆尝试"},{"k":"D","t":"要警惕“常识”的负面影响"}],"answer":"B","multi":false,"explanation":"<p>文段开篇指出在社会文化变革中，要创新就必须要有新的思维，要突破原有的观念体系和知识框架，要对已经在社会蔓延的“常识”进行反思和批判，也就是要不局限于原有的“常识”。接着对已经在社会中蔓延的“常识”进行了解释，并通过转折词“但是”指出这种“常识”是有问题的，即限制和捆绑了人们的创造力，尾句指出我们需要不断地做各种尝试，故文段围绕“创新”和“常识”的话题，重点强调的是我们要如何进行创新，也就是要打破“常识”的限制，去做多种尝试，对应B项。<br>A项，文段重点强调的是如何进行创新，为对策，而该项为问题表述，非重点，排除；<br>C项，文段尾句还提到了“反思、修正”，该项表述片面，且“大胆尝试”表述不明确，排除；<br>D项，“‘常识’的负面影响”并非文段重点，且表述不明确，排除。<br>故正确答案为B。<br>【文段出处】《艺术的先锋力量和创新实践》</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"言语理解与表达"},"idx":16,"pid":"p7e519edba8"},{"qid":"5430279","no":16,"type":"片段阅读","module":"言语理解与表达","stem":"<p>军事指挥员在未来战场上的谋优制胜能力取决于其军事思维发展水平，而要形成良好的军事思维能力，必须把战争制胜机理搞透。不同的战争形态，遵循不同的制胜机理，需要不同的思维方式。凡是罔顾军事实践发展、囿于陈旧观念的军队，必然会在战争中受到惩罚。事实证明，按照机械化条件下作战方式培养出来的指挥员，如果固守传统思维，是不能打赢信息化战争的。不清楚未来作战的制胜机理，就不能在实战化训练中及时增添反映未来作战的新要素、新内容、新手段，导调就只能在“老一套”上转圈圈，就无法引领参训官兵确立符合未来作战需要的思维。<br>这段文字意在强调：</p>","options":[{"k":"A","t":"信息化战争对参战人员提出的新要求"},{"k":"B","t":"提升指挥员军事思维发展水平的途径"},{"k":"C","t":"培养方式对提升军事指挥员素质的影响"},{"k":"D","t":"研究战争制胜机理对军事指挥员的意义"}],"answer":"D","multi":false,"explanation":"<p>文段开篇介绍军事思维发展水平对军事指挥员谋优制胜的重要性，接下来通过对策标志词“必须”强调“战争制胜机理”对形成良好军事思维能力的必要性，之后正面指出不同战争形态对应不同制胜机理，随后通过反面论证说明了罔顾军事实践、囿于陈旧观念、固守传统思维等“不清楚未来作战的制胜机理”的情况会带来不良后果，故文段开篇给出对策，之后通过正反论证进行解释说明，意在强调搞透战争制胜机理对军事指挥员的重要性，对应D项。<br>A项，“信息化战争”对应反面论证部分，非文段重点，且“提出的新要求”表述不明确，并未提及主题词“战争制胜机理”，排除；<br>B、C两项，均缺少主题词“战争制胜机理”，偏离文段核心话题，排除。<br>故正确答案为D。<br>【文段出处】《锻造军事思维力》</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"言语理解与表达"},"idx":17,"pid":"p7e519edba8"},{"qid":"5430263","no":17,"type":"片段阅读","module":"言语理解与表达","stem":"<p>研究发现，光的照射可对人体组织修复产生积极影响。据此，使用激光或发光二极管来提高人体组织修复能力，能够减少疼痛和炎症。利用这一光生物调节技术，研究人员开发出一种巴掌大小、既薄又轻、能均匀发出柔和治疗光的贴片。该贴片只需贴在伤口处，就能祛除伤痛，并通过不断刺激伤口愈合过程中起关键作用的真皮细胞增殖和迁移，帮助伤口愈合。研究人员表示，通过控制发射光的数量，还可扩大贴片的应用范围，治疗皮肤癌、阿尔茨海默症和抑郁症等病症。<br>关于文中的“贴片”，下列说法不正确的是：</p>","options":[{"k":"A","t":"能够促进伤口愈合"},{"k":"B","t":"可自动调节发射光的数量"},{"k":"C","t":"可用于治疗阿尔茨海默症"},{"k":"D","t":"利用了光可促进人体组织修复的原理"}],"answer":"B","multi":false,"explanation":"<p>A项，根据“该贴片······帮助伤口愈合”可知，表述正确，排除；<br>B项，根据“研究人员表示，通过控制发射光的数量”可知，文段论述的是人为控制发射光的数量，故“自动调节发射光的数量”表述错误，当选；<br>C项，根据“还可扩大贴片的应用范围，治疗皮肤癌、阿尔茨海默症和抑郁症等病症”可知，表述正确，排除；<br>D项，根据“光的照射可对人体组织修复产生积极影响。据此，使用激光或发光二极管来提高人体组织修复能力，能够减少疼痛和炎症”可知，表述正确，排除。<br>本题为选非题，故正确答案为B。<br>【文段出处】中国军网《科技云|科技连着你我他》</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"言语理解与表达"},"idx":18,"pid":"p7e519edba8"},{"qid":"5430269","no":18,"type":"语句表达","module":"言语理解与表达","stem":"<p>在互联网社交化、移动化背景下，算法应用使广告的个性化、强互动和精准性特征变得非常突出，<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。一方面，广告效果归因变得更加复杂。用户在多个社交平台中积极互动，消费者跨设备、跨媒体、线上线下行为交叉的情况也越来越多，如何精确测量单一平台的广告效果成为现实问题。另一方面，目前互联网广告常用的方法都无法追踪用户在其他渠道中的转化。以视频信息流广告为代表的一类广告存在着极强的推荐、分享等性质，用户与之相关的消费行为可能是在其他渠道中完成的。<br>填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"广告效果转化呈现跨界的特性"},{"k":"B","t":"传统的广告测量方法面临挑战"},{"k":"C","t":"广告从投放到获得收益存在诸多环节"},{"k":"D","t":"算法应用在广告效果归因上具有局限性"}],"answer":"B","multi":false,"explanation":"<p>横线出现在文段开头，需结合后文内容进行分析。后文从两方面进行了具体论述，一方面指出了广告效果归因变得复杂，即精确测量单一平台的广告效果成为了现实问题，另一方面论述了目前互联网广告常用的方法均无法精准追踪用户的转化，两方面内容均强调目前的方法无法精准测量广告效果，故横线处总领后文，也应该体现出目前的广告测量方法面临挑战，对应B项。<br>A项，“跨界的特性”仅对应“一方面”的内容，表述片面，排除；<br>C项，“从投放到获得收益”文段并未提及，衔接不当，排除；<br>D项，“算法应用的局限性”文段并未提及，衔接不当，排除。<br>故正确答案为B。<br>【文段出处】《增效度量：一种在线实验的广告效果测量新方法》</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"言语理解与表达"},"idx":19,"pid":"p7e519edba8"},{"qid":"5430284","no":19,"type":"片段阅读","module":"言语理解与表达","stem":"<p>牡丹和玉兰都不会在正月里开花，但是《岁朝图》里却出现这两种花卉，并且都代表“玉堂富贵”的意思。古人为了让这些花不按时令盛开，想到了一个办法，叫唐花，有时也写成火字旁的“煻”，煻就是烧火的意思，类似我们今天的温室技术。冬天在温室里加温，催花早放。这样的技术其实在汉代就已经有了，不过在汉代的时候更多是为了满足皇帝冬天吃蔬菜的需求。<br>这段文字意在说明：</p>","options":[{"k":"A","t":"《岁朝图》里牡丹和玉兰花的象征意义"},{"k":"B","t":"“唐花”这一专门术语的由来以及含义"},{"k":"C","t":"我国古代已经出现了实用的温室技术"},{"k":"D","t":"温室技术源于皇帝冬天吃蔬菜的需求"}],"answer":"C","multi":false,"explanation":"<p>文段开篇指出原本在正月里不会开花的“牡丹”和“玉兰”在《岁朝图》里均有出现，且具有一定的寓意，接着指出古人是利用“唐花”的技术来改变花朵盛开时令的，“唐花”的技术类似于今天的温室技术，尾句通过指代词“这样的技术”指代前文得出结论，强调温室技术在古代早已出现并得到应用，对应C项。<br>A项，对应文段开篇引出话题部分，非重点，排除；<br>B项，文段并未论述“唐花”的含义，无中生有，且文段论述了这一技术在古代的具体应用，并非单纯介绍这一术语的由来，排除；<br>D项，文段仅提到温室技术在古代可以满足皇帝冬天吃蔬菜的需求，并未说明温室技术来源于此，无中生有，排除。<br>故正确答案为C。<br>【文段出处】光明网《岁朝清供之插花》</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"言语理解与表达"},"idx":20,"pid":"p7e519edba8"},{"qid":"5430301","no":20,"type":"片段阅读","module":"言语理解与表达","stem":"<p>科学家观察了超过2500次拥抱后发现，在分别、团聚等情绪激动的拥抱中，人们身体容易向左倾斜；在街头陌生人间未投入情感的拥抱中，身体则更多地向右倾斜。科学家解释说，大脑右半球控制着左侧身体，并负责处理正面和负面的激烈情绪，当人们拥抱对方时，大脑中情感和运动领域系统会相互影响，在迸发强烈情绪的瞬间引起身体左倾。如果拥抱只是走个过场，那么很可能就会表现出身体右倾。<br>最适合做这段文字标题的是：</p>","options":[{"k":"A","t":"拥抱不能“走过场”"},{"k":"B","t":"拥抱向左倾才是真情"},{"k":"C","t":"情感疏离“有迹可循”"},{"k":"D","t":"大脑控制下的身体表达"}],"answer":"B","multi":false,"explanation":"<p>文段开篇阐述一项实验结论，指出人们在情绪激动的拥抱中身体容易向左倾斜，而在未投入情感的拥抱中身体容易向右倾斜。接下来论述科学家的一系列解释，即拥抱时身体左倾是因受到强烈情绪的影响。故文段主要围绕“拥抱”这一核心话题展开论述，强调迸发激烈情绪时拥抱身体会向左倾斜，对应B项。<br>A项，文段只是客观阐述了拥抱方式与情绪之间的相互关系，“不能‘走过场’”无中生有，排除；<br>C、D两项，均偏离文段核心话题“拥抱”，排除。<br>故正确答案为B。<br>【文段出处】《拥抱，向左倾才是真情》</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"言语理解与表达"},"idx":21,"pid":"p7e519edba8"},{"qid":"5430304","no":21,"type":"片段阅读","module":"言语理解与表达","stem":"<p>舰船类部队装备型号多，使得不同岗位的船员都有不同的学习训练需求，客观上加大了军事院校集中组织培训的难度。与此同时，船用装备结构复杂、构件精密，操作维修的技术含量高，人才培养周期较长。以机电岗位为例，从刚接触设备到能够单独操作设备、处理机械故障，一般要3~5年的培养期。如仅仅依靠军队系统培养人才，既会造成资源浪费，也会影响发展质量。因此只有把舰船类人才培养的眼光投向社会，充分借助地方平台载体，拓宽培养渠道，才能不断提升人才培养质量。<br>这段文字意在强调舰船类部队人才培养要：</p>","options":[{"k":"A","t":"提高培训质量"},{"k":"B","t":"缩短培养周期"},{"k":"C","t":"创新培养模式"},{"k":"D","t":"加大培训力度"}],"answer":"C","multi":false,"explanation":"<p>文段开篇通过“与此同时”并列阐述两方面的问题，即军事培训难度大以及人才培养周期长，随后指出仅依靠军队系统培养人才存在弊端，尾句“因此”总结前文，并提出对策，指出舰船类人才培养要将目光投向社会，发挥地方平台的作用，拓宽培养渠道。故文段重点强调舰船类人才培养不要局限在军队系统，要将目光投向社会，发挥地方平台作用，拓宽培养渠道，即寻找新的方式，对应C项。<br>A、D两项，“提高培训质量”“加大培训力度”文段均未提及，无中生有，排除；<br>B项，“缩短培养周期”对应“一般要3~5年的培养期”，非重点且表述片面，排除。<br>故正确答案为C。<br>【文段出处】《浅析军民融合式工程装备人才培养》</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"言语理解与表达"},"idx":22,"pid":"p7e519edba8"},{"qid":"5430285","no":22,"type":"片段阅读","module":"言语理解与表达","stem":"<p>斑马鱼和蝾螈等少数脊椎动物具有肢体和内脏器官再生的能力，比如成年斑马鱼的心室被切除20%后，其心脏组织在2个月内可完全再生。对于小鼠而言，在胚胎时期的第10~12天以及出生后的第4~14天左右，其心肌细胞可以分裂增殖，而成年小鼠的心肌细胞几乎已经不能分裂增殖，心脏组织一般不再具有再生能力。人类亦是如此，尽管有研究显示成年人的心肌细胞有极低程度的更新，然而，绝大部分心肌细胞已不再分裂增殖。而细胞不分裂增殖，相关基因突变就不会累积在细胞的基因组中，心肌细胞就不会变成肿瘤细胞。相反，肝脏、肠道上皮、皮肤等组织器官再生能力强、细胞分裂增殖旺盛，导致肿瘤相关基因突变累积在细胞基因组中的概率大幅增加，因而更加容易出现肿瘤。<br>根据这段文字，下列说法正确的是：</p>","options":[{"k":"A","t":"肿瘤细胞会导致相关基因突变"},{"k":"B","t":"成年人的心肌细胞不能分裂增殖"},{"k":"C","t":"细胞分裂增殖旺盛的器官更易得肿瘤"},{"k":"D","t":"成年斑马鱼的心室被切除后可完全再生"}],"answer":"C","multi":false,"explanation":"<p>A项，根据“肝脏、肠道上皮、皮肤等组织器官再生能力强、细胞分裂增殖旺盛，导致肿瘤相关基因突变累积在细胞基因组中的概率大幅增加，因而更加容易出现肿瘤”可知，是“相关基因突变”导致出现“肿瘤细胞”，因果倒置，排除；<br>B项，根据“尽管有研究显示成年人的心肌细胞有极低程度的更新”可知，表述过于绝对，排除；<br>C项，根据“肝脏、肠道上皮、皮肤等组织器官再生能力强、细胞分裂增殖旺盛，导致肿瘤相关基因突变累积在细胞基因组中的概率大幅增加，因而更加容易出现肿瘤”可知，表述正确，当选；<br>D项，根据“比如成年斑马鱼的心室被切除20%后，其心脏组织在2个月内可完全再生”可知，文段仅介绍心室20%被切除的情况，“心室被切除”表述错误，排除。<br>故正确答案为C。<br>【文段出处】《心脏为何很少得癌》</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"言语理解与表达"},"idx":23,"pid":"p7e519edba8"},{"qid":"5430287","no":23,"type":"片段阅读","module":"言语理解与表达","stem":"<p>在我国的传统花卉中，紫薇花算得上是名花之一。紫薇树姿优美，花色艳丽，花期可长达数月，素有“百日红”之美誉。南宋《全芳备祖》的作者陈景沂，甚至将紫薇花赞为“花之圣”。按常理来说，这种艳丽如霞的奇葩，应深受历代文人墨客的青睐。但奇怪的是，古人虽留下许多歌咏紫薇的佳作，却在“绘事”方面甚少留下墨迹。<br>这段文字接下来最可能说的是：</p>","options":[{"k":"A","t":"紫薇花这个美丽名称的由来"},{"k":"B","t":"紫薇花为何被称为“花之圣”"},{"k":"C","t":"历代诗人歌咏紫薇花的名篇"},{"k":"D","t":"古代画家为何很少画紫薇花"}],"answer":"D","multi":false,"explanation":"<p>本题为接语选择题，通读全文，重点关注文段最后论述的核心话题。文段开篇指出紫薇花为名花，随后指出紫薇树的特点，接下来用南宋陈景沂的例子说明紫薇花为“花之圣”，应受文人墨客的青睐，歌咏紫薇的佳作很多，文段最后通过“却”转折引出重点，即古人在“绘事”方面的作品很少，结合文意可知，“绘事”即画紫薇花，故接下来论述的核心话题应继续围绕“画紫薇花的作品很少”展开，D项“古代画家为何很少画紫薇花”符合文意，当选。<br>A项，“美丽名称的由来”与文段最后讨论的核心话题不一致，排除；<br>B项，“花之圣”为前文例子的内容，与文段最后讨论的核心话题不一致，排除；<br>C项，“歌咏紫薇花的名篇”为文段最后转折前的内容，与文段最后讨论的核心话题不一致，排除。<br>故正确答案为D。<br>【文段出处】羊城晚报《浅谈历代画家为何都很少画紫薇花？》</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"言语理解与表达"},"idx":24,"pid":"p7e519edba8"},{"qid":"5430318","no":24,"type":"片段阅读","module":"言语理解与表达","stem":"<p>在电商业、快递业高速发展的背景下，多家企业纷纷进军无人机物流领域，将其视为降低成本、提高效率之举。无人机送快递看上去有很多优势，比如可到达传统物流难以到达的偏远地区，可让快递在交通拥堵的城市快起来等。但从现实情况看，无人机送快递不会那么快实现。目前拿到“证”的企业，只能在批准的空域内试点飞行，而且无人机不直接面对普通用户，只是将物品送到某个配送点。此外，限制无人机物流广泛应用的另一个原因是安全问题，这既指无人机自身安全，也是指快件安全，更是指公众人身及财产安全。<br>这段文字主要介绍：</p>","options":[{"k":"A","t":"当前无人机配送难以普及的原因"},{"k":"B","t":"企业重视发展无人机物流的动机"},{"k":"C","t":"安全问题对无人机物流的重要意义"},{"k":"D","t":"无人机配送在现代物流领域的地位"}],"answer":"A","multi":false,"explanation":"<p>文段开篇引出“无人机物流”这个话题，并指出无人机送快递的诸多优势，接下来通过转折词“但”强调无人机送快递不会那么快实现，之后通过并列关联词“此外”分别从拿证企业角度和安全角度对前文观点进行原因解释，故文段主要强调无人机送快递不会那么快实现，对应A项。<br>B项，“重视发展无人机物流的动机”对应首句，为转折之前的内容，非重点，排除；<br>C项，“安全问题”对应“此外”之后的内容，属于解释说明，非重点且表述片面，排除；<br>D项，“在现代物流领域的地位”文段并未提及，无中生有，排除。<br>故正确答案为A。<br>【文段出处】法制日报《无人机快递，要以安全为先》</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"言语理解与表达"},"idx":25,"pid":"p7e519edba8"},{"qid":"5430427","no":25,"type":"语句表达","module":"言语理解与表达","stem":"<p>。新中国成立以来，很多画家借用西方的一些画法创作山水画，大多不太成功，也很难得到国人的认可。在这方面较为成功的是李可染和赖少其。他们都有深厚的传统文化功底，年轻时向传统大家学习，精研书法，长期写生。在打牢传统的各种基础后，李可染将光引入艺术表现，尤善用积墨画逆光；赖少其学习西方印象派等画法，借鉴西洋画的着色方式，和传统融合得很好。所以，他们笔下的祖国河山仍然体现出雄浑厚重、大气磅礴的中国精神。<br>填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"中西融合是二十世纪中国画面对的世纪课题"},{"k":"B","t":"中国画具有独特的文化特质和内在发展逻辑"},{"k":"C","t":"中国画家借鉴外来艺术时需有良好的传统功底"},{"k":"D","t":"借鉴西洋画艺术手法取得成功的中国画家很少"}],"answer":"A","multi":false,"explanation":"<p>横线在文段开头，需结合后文综合分析。文段首先介绍自新中国成立以来，很少有中国画家通过借用西方画法创作山水画获得成功，随后用李可染和赖少其这两位创作较为成功的画家的经验进行举例，并通过“所以”进行总结，说明将中国传统画法与西方画法结合后会创作出优秀的山水画。故文段重在强调新中国成立以后，中国传统画法与西方画法的结合是我国画家所要面临的问题，对应A项。<br>B项，重在强调中国画的文化内涵，缺少文段主题词“中西融合”，排除；<br>C项，文段重点论述“中西融合”，即将中国传统画法与西方画法融合，而“中国画家借鉴外来艺术时需有良好的传统功底”强调良好的功底是借鉴外来艺术的必要条件，逻辑表述错误，排除；<br>D项，重在强调“中西融合”后取得成功的中国画家很少，而文段重在通过成功画家的经验指出将中国传统画法与西方画法结合会取得成功，偏离了文段中心，排除。<br>故正确答案为A。<br>【文段出处】《美在河山 大气磅礴（逐梦70年）》</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"言语理解与表达"},"idx":26,"pid":"p7e519edba8"},{"qid":"5430321","no":26,"type":"片段阅读","module":"言语理解与表达","stem":"<p>研究人员介绍，来源于化脓链球菌的Cas9核酸酶现已广泛应用于水稻基因组编辑，有效促进了水稻功能基因组学研究和分子育种进程。Cas9在进行基因组编辑的过程中需要识别、结合一段位于编辑位点靶DNA序列末端的保守NGG序列（该保守序列被称为PAM识别序列，N为碱基A/T/G/C中任意一种）。PAM识别序列的存在极大限制了Cas9在基因组范围内的打靶序列选择，尤其在进行单碱基编辑替换时，由于待编辑靶碱基位置是固定的，周边若无NGG序列的话，基本无法进行靶碱基的编辑替换。<br>这段文字意在说明：</p>","options":[{"k":"A","t":"PAM识别序列的特点和作用"},{"k":"B","t":"Cas9基因编辑方法的特殊性"},{"k":"C","t":"Cas9对水稻基因组编辑的重要性"},{"k":"D","t":"PAM识别序列对Cas9基因组编辑时的影响"}],"answer":"D","multi":false,"explanation":"<p>文段开篇指出Cas9核酸酶已广泛应用于水稻基因组编辑，接着指出Cas9在基因组编辑时需要识别PAM序列，随后指出PAM识别序列极大限制Cas9在基因组范围内的打靶序列选择，并强调在进行单碱基编辑替换时，如果没有PAM识别序列将无法进行靶碱基的编辑替换，故文段重在强调PAM识别序列对Cas9基因组编辑时产生的影响，对应D项。<br>A项，未提及文段的主题词“Cas9”，偏离文段核心话题，排除；<br>B、C两项，均未提及文段另一主题词“PAM 识别序列”，偏离文段核心话题，排除。<br>故正确答案为D。<br>【文段出处】《水稻基因组编辑工具盒再添新成员》</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"言语理解与表达"},"idx":27,"pid":"p7e519edba8"},{"qid":"5430324","no":27,"type":"片段阅读","module":"言语理解与表达","stem":"<p>市场交易是市场机制有效配置资源的主要形式，而价格信号则是市场交易的指挥棒。国际资源配置最有效率的方式无疑是自由贸易。贸易保护主义旨在通过提高关税、设置贸易壁垒、采用反倾销反补贴等手段提高进口商品价格，阻止国外生产效率高且物美价廉的商品或服务进入本国市场。从表面上看，贸易保护主义保护了国内产业与就业安全，但实际上保护的是低效率生产，会造成商品或服务价格信号失真，使资源配置到没有比较优势的产业，而真正具有比较优势的产业却因得不到足够资源而难以持续发展。贸易保护主义还会对被保护产业的上下游关联产业产生影响，引起系统性的价格信号失真与资源配置扭曲。<br>这段文字主要介绍：</p>","options":[{"k":"A","t":"实施贸易保护主义的消极影响"},{"k":"B","t":"贸易保护主义得以实现的基本手段"},{"k":"C","t":"自由贸易与贸易保护主义的主要区别"},{"k":"D","t":"国际市场中资源有效配置的最佳方式"}],"answer":"A","multi":false,"explanation":"<p>文章开篇介绍了市场机制资源配置与国际资源配置的有效方式，随后引出贸易保护主义的话题，介绍了贸易保护主义的手段及目的。接着用转折词“但实际上”重点强调实行贸易保护主义会让一些产业难以持续发展，尾句通过“还”继续介绍实行贸易保护主义会带来的后果。故文段重在强调实行贸易保护主义带来的消极影响，对应A项。<br>B项“得以实现的基本手段”、D项“资源有效配置的最佳方式”均对应转折之前的内容，非重点，排除；<br>C项，“主要区别”文段未提及，无中生有，且“与”强调自由贸易和贸易保护主义之间为并列关系，但文段核心话题应为“贸易保护主义”，与文意不符，排除。<br>故正确答案为A。<br>【文段出处】人民日报《贸易保护主义贻害世界》</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"言语理解与表达"},"idx":28,"pid":"p7e519edba8"},{"qid":"5430326","no":28,"type":"片段阅读","module":"言语理解与表达","stem":"<p>人体需要的碳水化合物主要靠谷类提供。碳水化合物进入体内后转化为糖分，再进一步转化为维持人体机能的热量。糖分与热量之间的转化需要胰岛素的参与，胰岛素对葡萄糖有降解的作用。如果长期不吃或者少吃米饭，转化的葡萄糖量减少，胰岛素分泌就会减少，胰岛素的工作节奏被打乱，久而久之会给糖尿病提供可乘之机。<br>这段文字意在说明：</p>","options":[{"k":"A","t":"碳水化合物是人体所必需的"},{"k":"B","t":"不吃谷类食物可能会得糖尿病"},{"k":"C","t":"改善饮食结构可有效治疗糖尿病"},{"k":"D","t":"糖尿病的病因是胰岛素分泌紊乱"}],"answer":"B","multi":false,"explanation":"<p>文章开篇引出话题，说明谷类是人体所需碳水化合物的主要来源，接着具体讲述了碳水化合物转化为热量的过程，并指出其中需要胰岛素的参与；尾句引出重点，即长期不吃或少吃米饭，会导致胰岛素分泌减少、工作节奏被打乱，进而可能会给糖尿病可乘之机。故文章重点论述了长期不吃或少吃米饭（谷物）可能会得糖尿病，对应B项。<br>A项，“碳水化合物是人体所必需的”对应文中首句引出话题的内容，非重点，排除；<br>C项，“有效治疗糖尿病”文中并未提及，且改善饮食结构充其量只能“预防”糖尿病，排除；<br>D项，“胰岛素分泌紊乱”非重点，其根本原因还是因为“谷物”摄取不足，排除。<br>故正确答案为B。<br>【文段出处】《不吃米饭更容易得糖尿病》</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"言语理解与表达"},"idx":29,"pid":"p7e519edba8"},{"qid":"5430329","no":29,"type":"片段阅读","module":"言语理解与表达","stem":"<p>阿宝十岁，邻居蓓蒂六岁。两个人从假三层爬上屋顶，瓦片温热，眼里是半个卢湾区，前面香山路，东面复兴公园，东面偏北，看见祖父独幢洋房一角，西面后方，皋兰路尼古拉斯东正教堂，三十年代俄侨建立，据说是纪念苏维埃处决的沙皇，尼古拉二世，打雷闪电阶段，阴森可惧，太阳底下，比较养眼。<br>根据这段文字，能够确定的历史事实是哪一项？</p>","options":[{"k":"A","t":"尼古拉斯东正教堂坐落在西面后方一角"},{"k":"B","t":"尼古拉斯东正教堂在太阳底下比较养眼"},{"k":"C","t":"尼古拉斯东正教堂三十年代由俄侨建立"},{"k":"D","t":"尼古拉斯东正教堂是为纪念尼古拉二世"}],"answer":"C","multi":false,"explanation":"<p>A项，根据“两个人从假三层爬上屋顶······西面后方，皋兰路尼古拉斯东正教堂”可知，尼古拉斯东正教堂坐落于“屋顶”所在房屋的西面后方，而选项并未以“屋顶”所在的房屋为参照物，“西面后方”范围扩大，排除；<br>B项，根据“皋兰路尼古拉斯东正教堂，三十年代俄侨建立，据说是纪念苏维埃处决的沙皇······太阳底下，比较养眼”可知，“据说”意为根据别人说，无法确定尼古拉斯东正教堂在太阳底下比较养眼为事实，排除；<br>C项，根据“皋兰路尼古拉斯东正教堂，三十年代俄侨建立”可知，表述正确，当选；<br>D项，根据“皋兰路尼古拉斯东正教堂，三十年代俄侨建立，据说是纪念苏维埃处决的沙皇，尼古拉二世”可知，“据说”意为根据别人说，无法确定尼古拉斯东正教堂的建立是为纪念尼古拉二世为事实，排除。<br>故正确答案为C。<br>【文段出处】小说《繁花》</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"言语理解与表达"},"idx":30,"pid":"p7e519edba8"},{"qid":"5430331","no":30,"type":"片段阅读","module":"言语理解与表达","stem":"<p>用不了几十年，人工智能就会超越多种人类自认独有的能力。对我们这一代人来说，这是个巨大的挑战，也许我们需要“非理性”地应对。计算机占领了曾专属于人类的工作——那些需要知识、策略甚至创造力的工作。在这种“劳动分工”之下，我们应把人类的工作定位在与机器互补，而非与之相抗衡上。重视机器带来的挑战，意味着我们需要作出改变，刻不容缓。同时，相信创造力是人类特有的价值，即使机器超越人类，我们仍拥有地球上最具创造力的脑袋，里面装着天马行空的想法和深沉复杂的情感。<br>下列哪一说法与作者的观点不相符？</p>","options":[{"k":"A","t":"人类应该及时应对人工智能带来的挑战"},{"k":"B","t":"人类的创造力不会被人工智能完全取代"},{"k":"C","t":"人类的知识是与人工智能相抗衡的基础"},{"k":"D","t":"人类与人工智能可在不同领域实现互补"}],"answer":"C","multi":false,"explanation":"<p>A项，根据“重视机器带来的挑战，意味着我们需要作出改变，刻不容缓”可知，“及时应对人工智能带来的挑战”表述正确，排除；<br>B项，根据“相信创造力是人类特有的价值，即使机器超越人类，我们仍拥有地球上最具创造力的脑袋”可知，“人类的创造力不会被人工智能完全取代”表述正确，排除；<br>C项，根据“我们应把人类的工作定位在与机器互补，而非与之相抗衡上”可知，“与人工智能相抗衡”与文意相悖，且“人类的知识是抗衡的基础”无中生有，当选；<br>D项，根据“我们应把人类的工作定位在与机器互补，而非与之相抗衡上”可知，“在不同领域实现互补”表述正确，排除。<br>本题为选非题，故正确答案为C。<br>【文段出处】观点《人类最后的价值》</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"言语理解与表达"},"idx":31,"pid":"p7e519edba8"},{"qid":"5430510","no":1,"type":"图形推理","module":"判断推理","stem":"<p>从所给的四个选项中选择最合适的一个填入问号处，使之呈现一定的规律性：</p><p><img src=\"assets/img/timu/185294fb01f3ec1.png\" class=\"fig\" style=\"width:600px;height:277px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"A","multi":false,"explanation":"<p>观察发现，题干图形均出现黑块与白块，但数量、位置等均无规律，将两幅图相邻比较发现，黑块的位置存在规律，即题干图形的每个拐角处均为黑块，故“？”处图形的每个拐角处应均为黑块，B、C、D三项均有拐角处不是黑块（如下图所示），只有A项满足规律。</p><p><img src=\"assets/img/timu/185295b621bf9b0.png\" class=\"fig\" style=\"width:500px;height:185px;\"></p><p>故正确答案为A。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":32,"pid":"p7e519edba8"},{"qid":"5430899","no":2,"type":"图形推理","module":"判断推理","stem":"<p>从所给的四个选项中选择最合适的一个填入问号处，使之呈现一定的规律性：</p><p><img src=\"assets/img/timu/18529c4ffb19b98.png\" class=\"fig\" style=\"width:600px;height:283px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"B","multi":false,"explanation":"<p>图形元素组成不同，且无明显属性规律，考虑数量规律。观察发现，题干每幅图都是由直线构成，存在直线相交且出现明显的直角，优先考虑数直角数。图形大多分为内、外两部分，考虑分开数直角数。外框图形直角数依次为0、1、2、3、4、“？”，所以“？”处应该选择一个外框直角数为5的图形，只有B项符合。<br>故正确答案为B。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":33,"pid":"p7e519edba8"},{"qid":"5430358","no":3,"type":"图形推理","module":"判断推理","stem":"<p>从所给的四个选项中选择最合适的一个填入问号处，使之呈现一定的规律性：</p><p><img src=\"assets/img/timu/1852901d85cb509.png\" class=\"fig\" style=\"width:560px;height:265px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"A","multi":false,"explanation":"<p>元素组成相同，优先考虑位置规律。题干图形均出现了二十五宫格，考虑内外分开看平移。观察发现，内圈的黑块每次逆时针平移1格，外圈的黑块每次顺时针平移2格，只有A项符合。</p><p><img src=\"assets/img/timu/1852a1ad1996f46.png\" class=\"fig\" style=\"width:695px;height:326px;\"></p><p>故正确答案为A。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":34,"pid":"p7e519edba8"},{"qid":"5430354","no":4,"type":"图形推理","module":"判断推理","stem":"<p>从所给的四个选项中选择最合适的一个填入问号处，使之呈现一定的规律性：</p><p><img src=\"assets/img/timu/1852900b145aa0e.png\" class=\"fig\" style=\"width:700px;height:297px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"C","multi":false,"explanation":"<p>元素组成相似，优先考虑样式规律。观察发现，题干图形均存在黑块、白块以及空白区域，且黑块数量不成规律，优先考虑黑白运算。第一组图形的运算规律为：黑+黑=空，空+空=空，黑+白＝黑，白+白＝空，空+黑=黑，白+空=白，空+白=白，黑+空=黑，第二组图形运用此规律，只有C项符合。<br>故正确答案为C。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":35,"pid":"p7e519edba8"},{"qid":"5430505","no":5,"type":"图形推理","module":"判断推理","stem":"<p>从所给的四个选项中选择最合适的一个填入问号处，使之呈现一定的规律性：</p><p><img src=\"assets/img/timu/18529646ed9fff7.png\" class=\"fig\" style=\"width:700px;height:308px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"C","multi":false,"explanation":"<p>元素组成不同，优先考虑属性规律。观察发现，题干图形出现等腰元素，优先考虑对称性。第一组图中，每个图形均只有一条纵向的对称轴，第二组图中，前两幅图形也均只有一条纵向的对称轴，所以？处应填入只有一条纵向对称轴的图形，排除B、D两项。继续观察发现，题干图形出现明显的空白面，考虑面数量。第一组图中，图形的面数量依次为2、3、4，第二组图中，图形的面数量依次为2、3、？，故？处应选择一个面数量为4的图形，只有C项符合。<br>故正确答案为C。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":36,"pid":"p7e519edba8"},{"qid":"5430439","no":6,"type":"图形推理","module":"判断推理","stem":"<p>把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：</p><p><img src=\"assets/img/timu/185294442b94e1e.png\" class=\"fig\" style=\"width:650px;height:175px;\"></p>","options":[{"k":"A","t":"①③⑤，②④⑥"},{"k":"B","t":"①③⑥，②④⑤"},{"k":"C","t":"①②③，④⑤⑥"},{"k":"D","t":"①④⑤，②③⑥"}],"answer":"D","multi":false,"explanation":"<p>本题为分组分类题目。观察发现，题干每幅图形均由两幅形状相同但位置不同的元素组成，考虑位置规律。图①④⑤中的一个元素图形旋转<img src=\"assets/img/gongshi/formula-baa9dcf22db28066.png\" class=\"tex\">后可得到另一个元素图形的形状，图②③⑥中的一个元素图形旋转<img src=\"assets/img/gongshi/formula-5a9999d9b71843f6.png\" class=\"tex\">后可得到另一个元素图形的形状，即图①④⑤为一组，图②③⑥为一组。</p><p>故正确答案为D。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":37,"pid":"p7e519edba8"},{"qid":"5430356","no":7,"type":"图形推理","module":"判断推理","stem":"<p>把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：</p><p><img src=\"assets/img/timu/1852900f3d3e333.png\" class=\"fig\" style=\"width:700px;height:171px;\"></p>","options":[{"k":"A","t":"①②⑤，③④⑥"},{"k":"B","t":"①③④，②⑤⑥"},{"k":"C","t":"①④⑤，②③⑥"},{"k":"D","t":"①⑤⑥，②③④"}],"answer":"A","multi":false,"explanation":"<p>本题为分组分类题目。观察发现，题干图形中明显出现相切，其中图①②⑤中直线均与1个圆相切，图③④⑥中直线均与2个圆相切，故图①②⑤一组，图③④⑥一组。<br>故正确答案为A。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":38,"pid":"p7e519edba8"},{"qid":"5430365","no":8,"type":"图形推理","module":"判断推理","stem":"<p>从所给的四个选项中选择最合适的一个填入问号处，使之呈现一定的规律性：</p><p><img src=\"assets/img/timu/185290437a1bd4b.png\" class=\"fig\" style=\"width:503px;height:600px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"B","multi":false,"explanation":"<p>题干图形元素组成不同，优先考虑属性规律。观察发现，题干图形较为规整，考虑对称性。九宫格第一列均为竖轴对称图形，第二列均为横轴对称图形，第三列前两个图形均为既横轴对称又竖轴对称的图形，故“？”处应为既横轴对称又竖轴对称的图形，只有B项满足。<br>故正确答案为B。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":39,"pid":"p7e519edba8"},{"qid":"5430410","no":9,"type":"图形推理","module":"判断推理","stem":"<p>左图给定的是纸盒的外表面，右边哪项能由它折叠而成？</p><p><img src=\"assets/img/timu/185291a42f5c827.png\" class=\"fig\" style=\"width:600px;height:169px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"C","multi":false,"explanation":"<p>将原展开图标上序号如下图，逐一进行分析。</p><p><img src=\"assets/img/timu/185291ad93e93f1.png\" class=\"fig\" style=\"width:600px;height:167px;\"></p><p>A项：选项右侧为面b，左侧为面a或面c，选项中左侧面上的实线与其和面b的公共边中点不相交，而展开图中面a与面c上的实线均和该面与面b的公共边中点相交，选项与展开图不一致，排除；</p><p><img src=\"assets/img/timu/185291b0404f865.png\" class=\"fig\" style=\"width:600px;height:160px;\"></p><p>B项：选项左侧为面d，右侧为面a或面c，选项中面d上的虚线与其和右侧面（面a或面c）的公共边中点相交，而展开图中面d上虚线与其和面b的公共边中点相交，选项与展开图不一致，排除；<br></p><p><img src=\"assets/img/timu/185291b258d9bb4.png\" class=\"fig\" style=\"width:600px;height:163px;\"></p><p>C项：选项由面b和面c构成，与展开图一致，当选；</p><p>D项：选项由面b和面d构成，以面b中引出实线的顶点为起点，沿面b顺时针画边（如下图所示），展开图中边3对应面d，而选项中边1对应面d，选项与展开图不一致，排除。</p><p><img src=\"assets/img/timu/185291b5d18a066.png\" class=\"fig\" style=\"width:600px;height:168px;\"></p><p>故正确答案为C。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":40,"pid":"p7e519edba8"},{"qid":"5430887","no":10,"type":"图形推理","module":"判断推理","stem":"<p>左图为给定的多面体，将其从任一面剖开，哪项不可能是该多面体的截面？</p><p><img src=\"assets/img/timu/18649c621a9c579.png\" class=\"fig\" style=\"width:626px;height:184px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"D","multi":false,"explanation":"<p>本题考查截面图，逐一分析选项。</p><p>A项：如下图所示，可以截出，排除；</p><p><img src=\"assets/img/timu/18649c664e3ec4b.png\" class=\"fig\" style=\"width:257px;height:238px;\"></p><p>B项：如下图所示，可以截出，排除；</p><p><img src=\"assets/img/timu/18649c6942e6ab7.png\" class=\"fig\" style=\"width:348px;height:283px;\"></p><p>C项：如下图所示，可以截出，排除；</p><p><img src=\"assets/img/timu/18649c6bd54d738.png\" class=\"fig\" style=\"width:291px;height:278px;\"></p><p>D项：无法截出，当选。</p><p>本题为选非题，故正确答案为D。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":41,"pid":"p7e519edba8"},{"qid":"5430362","no":11,"type":"定义判断","module":"判断推理","stem":"<p>发现不均衡套利是指通过发现和利用市场上的资源供给和需求不一致进行调配导致的盈利机会获利。<br>根据上述定义，下列不属于发现不均衡套利的是：</p>","options":[{"k":"A","t":"孔子的门生子贡在曹国与鲁国之间通过贱买贵卖来获利"},{"k":"B","t":"小王预见来年橄榄必然大获丰收，便买断了当地所有的榨油机，第二年高价出租获得巨额财富"},{"k":"C","t":"F汽车公司针对当时汽车价格昂贵、普通居民消费不起的状况，推出了价廉物美的T型车，迅速进入普通家庭"},{"k":"D","t":"20世纪80年代，中国农村出现大量富余劳动力，而工业产品又极为缺乏。因此将富余的农村劳动力组织起来生产工业产品，可以获利"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“通过发现和利用市场上的资源供给和需求不一致进行调配”、“导致的盈利机会获利”。<br>第二步：逐一分析选项。<br>A项：曹国与鲁国之间贱买贵卖，说明商品在两个空间上存在“市场上的资源供给和需求不一致”，通过这种商品的买卖，实现了对“供需不一致资源”的调配，从而创造“盈利机会”而获利，符合定义，排除；<br>B项：来年橄榄的大丰收会造成未来榨油机的供不应求，说明现在和未来两个时间上对于榨油机的供需是不一致的，符合“市场上的资源供给和需求不一致”，通过现在买断榨油机，第二年高价出租，实现了对“供需不一致资源”的调配，从而创造“盈利机会”而获利，符合定义，排除；<br>C项：仅提到目前汽车市场普通居民消费不起，F公司推出价廉物美的T型车，只是推出新产品，并不是对“供给和需求不一致进行调配”，不符合定义，当选；<br>D项：农村出现大量富余劳动力，体现出在农业方面劳动力供过于求，而工业产品极度缺乏，体现出工业方面劳动力供不应求，说明农业和工业两个领域产品市场和要素市场存在“供给和需求不一致”，通过将富余的农村劳动力组织起来生产工业产品，符合实现了对“供需不一致资源”的调配，从而创造“盈利机会”而获利，符合定义，排除。<br>本题为选非题，故正确答案为C。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":42,"pid":"p7e519edba8"},{"qid":"5430366","no":12,"type":"定义判断","module":"判断推理","stem":"<p>经济学中的“公用品”并不是指大家都在使用的物品，同时“私用品”也不是一个人使用的物品。公用品指一个人使用的过程中不排斥和影响他人使用的物品；而私用品指一个人在使用过程中会排斥或者影响其他人使用的物品。<br>根据上述定义，下列属于公用品的是：</p>","options":[{"k":"A","t":"会议室"},{"k":"B","t":"停车场"},{"k":"C","t":"小区草坪"},{"k":"D","t":"有线电视的信号"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>公用品：“使用过程中不排斥和影响他人使用”；<br>私用品：“使用过程中会排斥或影响他人使用”。<br>第二步：逐一分析选项。<br>A项：一个人在使用会议室时会影响其他人的使用，不符合“使用过程中不排斥和影响他人使用”，不符合“公用品”定义，排除；<br>B项：一个人在停车场停车时会影响其他人的使用，不符合“使用过程中不排斥和影响他人使用”，不符合“公用品”定义，排除；<br>C项：一个人在使用小区草坪时会影响其他人的使用，不符合“使用过程中不排斥和影响他人使用”，不符合“公用品”定义，排除；<br>D项：有线电视的信号可同时供多人使用，一个人使用时不会影响到其他人的使用，符合“使用过程中不排斥和影响他人使用”，符合“公用品”定义，当选。<br>故正确答案为D。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":43,"pid":"p7e519edba8"},{"qid":"5430368","no":13,"type":"定义判断","module":"判断推理","stem":"<p>机器学习专门研究计算机如何模拟人类的学习行为，以获取新的知识或技能，提高学习效率。通常使用数据或以往的经验，以此优化计算机程序的性能。<br>根据上述定义，下列不属于机器学习的是：</p>","options":[{"k":"A","t":"某公司通过海量数据，不断升级门禁考勤等场景的人脸识别技术的版本，将准确率从85%提高至99%"},{"k":"B","t":"科研小组分析人类学习行为，决定让计算机先选用简单的数据再选用复杂的数据依次训练，提升了计算机算法的准确率"},{"k":"C","t":"某高校统计学生核酸完成情况，利用算法识别核酸报告截图特定字符，自动生成结果，统计汇总时间由一小时缩短至两分钟"},{"k":"D","t":"某AI算法在数据量较少的情况下，通过模拟双方对抗情况获取训练数据，不断提升技巧，最终在网络游戏中达到职业选手水平"}],"answer":"C","multi":false,"explanation":"<p>第一步，找出定义关键词。<br>“使用数据或以往的经验”、“优化计算机程序的性能”。<br>第二步，逐一分析选项。<br>A项：某公司通过海量数据，不断升级人脸识别技术的版本，提高了准确率，符合“使用数据或以往的经验”、“优化计算机程序的性能”，符合定义，排除；<br>B项：科研小组让计算机选用不同难度的数据依次训练，提升了计算机算法的准确率，符合“使用数据或以往的经验”、“优化计算机程序的性能”，符合定义，排除；<br>C项：某高校利用算法识别核酸报告截图特定字符，缩短了统计汇总时间，并没有提升算法的性能，不符合“优化计算机程序的性能”，不符合定义，当选；<br>D项：某AI算法通过模拟双方对抗情况获取训练数据，不断提升技巧，符合“使用数据或以往的经验”、“优化计算机程序的性能”，符合定义，排除。<br>本题为选非题，故正确答案为C。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":44,"pid":"p7e519edba8"},{"qid":"5430370","no":14,"type":"定义判断","module":"判断推理","stem":"<p>弱关系社交，指以网络平台为载体，在陌生人之间展开的、不以加强彼此关系为目的的人际交往活动。<br>根据上述定义，下列不属于弱关系社交的是：</p>","options":[{"k":"A","t":"参与中国象棋小程序自动匹配对手的游戏"},{"k":"B","t":"为刚刚添加的微信好友的朋友圈动态点赞"},{"k":"C","t":"在网络直播平台对小视频评论进行再评论"},{"k":"D","t":"网络游戏过程中为提高游戏技术相互切磋"}],"answer":"B","multi":false,"explanation":"<p>第一步，找出定义关键词。<br>“以网络平台为载体”、“在陌生人之间展开的”、“不以加强彼此关系为目的”。<br>第二步，逐一分析选项。<br>A项：游戏对手是通过计算机程序自动匹配的，相互之间并不认识，符合“以网络平台为载体”、“在陌生人之间展开的”、“不以加强彼此关系为目的”，符合定义，排除；<br>B项：为刚刚添加的微信好友的朋友圈动态点赞，说明在成为微信好友前就有可能认识，不一定是陌生人，并且添加微信好友的目的就是加强相互之间的联系，不符合“在陌生人之间展开的”、“不以加强彼此关系为目的”，不符合定义，当选；<br>C项：在网络直播平台对小视频评论进行再评论，符合“以网络平台为载体”、“在陌生人之间展开的”、“不以加强彼此关系为目的”，符合定义，排除；<br>D项：网络游戏过程中为提高游戏技术相互切磋，符合“以网络平台为载体”、“在陌生人之间展开的”、“不以加强彼此关系为目的”，符合定义，排除。<br>本题为选非题，故正确答案为B。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":45,"pid":"p7e519edba8"},{"qid":"5430372","no":15,"type":"定义判断","module":"判断推理","stem":"<p>审美意象是用来表达某种抽象的观念或者哲理的艺术形象，它是艺术家在构思过程中，将自己的审美情感、审美认识与客观的事物相融合，并以一定的艺术表达方式呈现出来的内心视像。<br>根据上述定义，下列不属于审美意象的是：</p>","options":[{"k":"A","t":"鲁迅作品《祝福》中的人物“祥林嫂”"},{"k":"B","t":"“采菊东篱下，悠然见南山”中的“南山”"},{"k":"C","t":"漫画作品《三毛流浪记》中的人物“三毛”"},{"k":"D","t":"日常语句“太阳出来了，该起床了”中的“太阳”"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“艺术家在构思过程中”、“将自己的审美情感、审美认识与客观的事物相融合”、“以一定的艺术表达方式呈现出来的内心视像”。<br>第二步：逐一分析选项。<br>A项：“祥林嫂”是鲁迅作品《祝福》中的悲剧性人物，是旧中国农村劳动妇女的典型，符合“艺术家在构思过程中”、“将自己的审美情感、审美认识与客观的事物相融合”、“以一定的艺术表达方式呈现出来的内心视像”，符合定义，排除；<br>B项：“南山”是陶渊明诗句中的艺术形象，该句诗表现了诗人悠然闲适的生活态度，诗人将自己的情感和客观事物相融合，符合“艺术家在构思过程中”、“将自己的审美情感、审美认识与客观的事物相融合”、“以一定的艺术表达方式呈现出来的内心视像”，符合定义，排除；<br>C项：“三毛”是漫画作品《三毛流浪记》中一个身世凄凉、饥寒交迫、受尽欺辱、贫穷得只剩下三根头发的中国儿童形象，符合“艺术家在构思过程中”、“将自己的审美情感、审美认识与客观的事物相融合”、“以一定的艺术表达方式呈现出来的内心视像”，符合定义，排除；<br>D项：“太阳出来了，该起床了”中的“太阳”是用在日常语句中，没有体现艺术家创作作品的构思过程和艺术的表达方式，不符合“艺术家在构思过程中”、“将自己的审美情感、审美认识与客观的事物相融合”、“以一定的艺术表达方式呈现出来的内心视像”，不符合定义，当选。<br>本题为选非题，故正确答案为D。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":46,"pid":"p7e519edba8"},{"qid":"5430380","no":16,"type":"定义判断","module":"判断推理","stem":"<p>脱敏作用是指对人重复呈现一个激发情绪的刺激，则该个体情绪化反应会逐渐消失。<br>根据上述定义，下列涉及脱敏作用的是：</p>","options":[{"k":"A","t":"小华幼年时曾被狗追咬过，成年后看到狗仍然会感到非常恐惧"},{"k":"B","t":"小孙爱玩含有暴力元素的游戏，生活中偶尔会模仿游戏中人物的行为"},{"k":"C","t":"小王近期经常观看犯罪题材的影片，认为外面的世界很危险，走夜路时常会担心有意外发生"},{"k":"D","t":"老师发现小明与女同学交谈时总会面红耳赤，就要求他每天主动和邻座女同学进行学习讨论"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“对人重复呈现一个激发情绪的刺激”、“该个体情绪化反应会逐渐消失”。<br>第二步：逐一分析选项。<br>A项：小华成年后看到狗仍然会感到非常恐惧，说明小华被狗追咬的恐惧没有消失，不符合“该个体情绪化反应会逐渐消失”，不符合定义，排除；<br>B项：小孙生活中模仿游戏中人物的暴力行为，说明含有暴力元素的游戏对他的影响并没有逐渐消失，不符合“该个体情绪化反应会逐渐消失”，不符合定义，排除；<br>C项：小王走夜路时常会担心有意外发生，说明看犯罪题材的影片对他的影响并没有逐渐消失，不符合“该个体情绪化反应会逐渐消失”，不符合定义，排除；<br>D项：小明与女同学交谈时总会面红耳赤，老师要求他每天主动和邻座女同学进行学习讨论，符合“对人重复呈现一个激发情绪的刺激”，符合定义，当选。<br>故正确答案为D。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":47,"pid":"p7e519edba8"},{"qid":"5430382","no":17,"type":"定义判断","module":"判断推理","stem":"<p>群体归属感是指个人体验到自己属于或应属于某一群体成员的意识，是个人隶属于或依赖于群体的需要，是一种人类社会性的表现。有了这种意识，个体在进行自己的活动、认知和评价时，就会自觉地维护这个群体的利益，并与群体内的其他成员在情感上发生共鸣。<br>根据上述定义，下列没有体现群体归属感的是：</p>","options":[{"k":"A","t":"中秋节时小韦与几个要好的朋友一起分享月饼"},{"k":"B","t":"王晓峰听到别人说他所在班级的坏话时很生气"},{"k":"C","t":"退役士兵小王常向他人说自己曾是某英雄连的"},{"k":"D","t":"小强外出时总自豪地在外衣上佩戴学校的校徽"}],"answer":"A","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“个人体验到自己属于或应属于某一群体成员的意识”、“个体在进行自己的活动、认知和评价时，会自觉地维护群体的利益”、“与群体内的其他成员在情感上发生共鸣”。<br>第二步：逐一分析选项。<br>A项：中秋节小韦与要好的朋友分享月饼，没有体现小韦感觉自己是某一群体的成员，也没有体现小韦自觉地维护群体的利益，不符合“个人体验到自己属于或应属于某一群体成员的意识”、“个体在进行自己的活动、认知和评价时，会自觉地维护群体的利益”，不符合定义，当选；<br>B项：王晓峰听到别人说他所在班级的坏话时很生气，体现了他感觉自己是班级这一群体的成员，符合“个人体验到自己属于或应属于某一群体成员的意识”、“个体在进行自己的活动、认知和评价时，会自觉地维护群体的利益”、“与群体内的其他成员在情感上发生共鸣”，符合定义，排除；<br>C项：退役士兵小王常向他人说自己曾是某英雄连的，体现了他感觉自己是连队这一群体的成员，符合“个人体验到自己属于或应属于某一群体成员的意识”、“个体在进行自己的活动、认知和评价时，会自觉地维护群体的利益”、“与群体内的其他成员在情感上发生共鸣”，符合定义，排除；<br>D项：小强外出时总自豪地在外衣上佩戴学校的校徽，体现了他感觉自己是学校这一群体的成员，符合“个人体验到自己属于或应属于某一群体成员的意识”、“个体在进行自己的活动、认知和评价时，会自觉地维护群体的利益”、“与群体内的其他成员在情感上发生共鸣”，符合定义，排除。<br>本题为选非题，故正确答案为A。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":48,"pid":"p7e519edba8"},{"qid":"5430383","no":18,"type":"定义判断","module":"判断推理","stem":"<p>多重趋避式冲突是指人们面对着两个或两个以上的目标，而目标又各自分别具有吸引和排斥两方面的作用，人们无法简单地选择一个目标而回避或拒绝另一个目标时的矛盾心态。<br>根据上述定义，下列体现多重趋避式冲突的是：</p>","options":[{"k":"A","t":"张女士在二胎问题上犹豫不决，既想儿女双全，又怕无力抚养"},{"k":"B","t":"周女士有一次难得的外省培训机会，可又放心不下家中年幼的孩子"},{"k":"C","t":"王先生有一笔闲置资金，用于炒股担心风险大，用于储蓄又嫌收益低"},{"k":"D","t":"李同学在收到研究生录取通知书的同时，又得到了心仪公司的入职邀请"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“人们面对着两个或两个以上的目标”、“目标各自分别具有吸引和排斥两方面的作用”、“人们无法简单地选择一个目标而回避或拒绝另一个目标时的矛盾心态”。<br>第二步：逐一分析选项。<br>A项：张女士面临的只有“生二胎”一个目标，儿女双全和无力抚养分别是目标的吸引方面和排斥方面，不符合“人们面对着两个或两个以上的目标”，不符合定义，排除；<br>B项：周女士面临的只有“省外培训”一个目标，放心不下家中年幼的孩子是目标的排斥方面，不符合“人们面对着两个或两个以上的目标”，不符合定义，排除；<br>C项：王先生面临“闲置资金炒股”和“闲置资金储蓄”两个目标，收益高和风险大是“闲置资金炒股”的吸引方面和排斥方面，风险低和收益低是“闲置资金储蓄”的吸引方面和排斥方面，王先生在两个目标中感到纠结矛盾，符合“人们面对着两个或两个以上的目标”、“目标各自分别具有吸引和排斥两方面的作用”、“人们无法简单地选择一个目标而回避或拒绝另一个目标时的矛盾心态”，符合定义，当选；<br>D项：李同学面临“研究生录取”和“心仪公司入职”两个目标，但并没有体现他在两个目标中感到纠结矛盾，不符合“人们无法简单地选择一个目标而回避或拒绝另一个目标时的矛盾心态”，不符合定义，排除。<br>故正确答案为C。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":49,"pid":"p7e519edba8"},{"qid":"5430384","no":19,"type":"定义判断","module":"判断推理","stem":"<p>功能文化区是按照人类社会的某项功能组织建立起来的，在空间结构上具有较固定的、确切的边界，其内部彼此之间因功能有一种互相联系从而确定其分布区范围的文化区。形式文化区是指不同性质的文化现象分布的范围，是某些具有相互联系的文化现象在空间分布上具有集中的核心区与模糊边界的文化地域单元。<br>根据上述定义，下列属于功能文化区的是：</p>","options":[{"k":"A","t":"城市中的外籍人员聚居区"},{"k":"B","t":"城市中的行为艺术聚集区"},{"k":"C","t":"城市郊区的垃圾集中处理区"},{"k":"D","t":"城市中的博物馆图书馆集中区"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>功能文化区：“按照人类社会的某项功能组织建立起来的”、“在空间结构上具有较固定的、确切的边界”、“内部彼此之间因功能的互相联系而确定其分布区范围的文化区”；<br>形式文化区：“某些具有相互联系的文化现象”、“在空间分布上具有集中的核心区与模糊边界的文化地域单元”。<br>第二步：逐一分析选项。<br>A项：城市中的外籍人员聚居区，不符合“按照人类社会的某项功能组织建立起来的”、“内部彼此之间因功能的互相联系而确定其分布区范围的文化区”，不符合“功能文化区”定义，排除；<br>B项：城市中的行为艺术聚集区，不符合“按照人类社会的某项功能组织建立起来的”、“内部彼此之间因功能的互相联系而确定其分布区范围的文化区”，不符合“功能文化区”定义，排除；<br>C项：城市郊区的垃圾集中处理区，不是文化区，不符合“内部彼此之间因功能的互相联系而确定其分布区范围的文化区”，不符合“功能文化区”定义，排除；<br>D项：城市中的博物馆图书馆集中区，符合“按照人类社会的某项功能组织建立起来的”，博物馆和图书馆在空间上具有明确的边界，且功能之间有联系，又属于文化区，符合“在空间结构上具有较固定的、确切的边界”、“内部彼此之间因功能的互相联系而确定其分布区范围的文化区”，符合“功能文化区”定义，当选。<br>故正确答案为D。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":50,"pid":"p7e519edba8"},{"qid":"5430386","no":20,"type":"定义判断","module":"判断推理","stem":"<p>表演型人格又称寻求注意型人格，是一种以过分情感化和夸张的言行吸引他人注意的人格。具有表演型人格的人易感情用事，自我中心，情绪多变，以致难以与周围人保持正常的社会关系。<br>根据上述定义，下列与表演型人格无关的是：</p>","options":[{"k":"A","t":"小邓喜欢穿奇装异服，希望吸引别人的注意"},{"k":"B","t":"小王具有表演才能，讲话时手舞足蹈、表情丰富"},{"k":"C","t":"小刘在人际交往受挫折时，表现出歇斯底里行为"},{"k":"D","t":"小顾没有几个知心朋友，但他经常说自己有很多知心朋友"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“过分情感化和夸张的言行”、“吸引他人注意”。<br>第二步：逐一分析选项。<br>A项：小邓喜欢穿奇装异服，属于夸张的行为，符合“过分情感化和夸张的言行”，希望吸引别人的注意，符合“吸引他人注意”，符合定义，排除；<br>B项：小王具有表演才能，讲话时手舞足蹈、表情丰富，属于夸张的行为，符合“过分情感化和夸张的言行”，符合定义，排除；<br>C项：小刘在人际交往受挫折时，表现出歇斯底里行为，属于过分情感化的行为，符合“过分情感化和夸张的言行”，符合定义，排除；<br>D项：小顾没有几个知心朋友，却说自己有很多知心朋友，这是属于夸大事实，而不是过分夸张，且其他选项均为行为上明显的夸张，D只是语言上的吹嘘，对比择优，该项最不明显，不符合“过分情感化和夸张的言行”，不符合定义，当选。<br>本题为选非题，故正确答案为D。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":51,"pid":"p7e519edba8"},{"qid":"5430378","no":21,"type":"类比推理","module":"判断推理","stem":"<p>声东：击西</p>","options":[{"k":"A","t":"围魏：救赵"},{"k":"B","t":"张冠：李戴"},{"k":"C","t":"安居：乐业"},{"k":"D","t":"说东：道西"}],"answer":"A","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>“声东击西”指为了迷惑敌人，表面上宣扬要攻打这一边，其实是攻打另一边，“声东”是为了“击西”，二者为方式目的对应关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：“围魏救赵”指袭击敌人后方的据点以迫使进攻之敌撤退的战术，“围魏”是为了“救赵”，二者为方式目的对应关系，与题干逻辑关系一致，当选；<br>B项：“张冠李戴”指姓张的人的帽子戴到姓李的人头上，比喻认错了对象或弄错了事实，二者不是方式目的对应关系，与题干逻辑关系不一致，排除；<br>C项：“安居乐业”指安定地生活，愉快地工作，二者为并列关系，与题干逻辑关系不一致，排除；<br>D项：“说东道西”指说东家，讲西家，形容信口议论，话语极多，二者为并列关系，与题干逻辑关系不一致，排除。<br>故正确答案为A。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":52,"pid":"p7e519edba8"},{"qid":"5430381","no":22,"type":"类比推理","module":"判断推理","stem":"<p>心宽：体胖</p>","options":[{"k":"A","t":"唇亡：齿寒"},{"k":"B","t":"鼻青：脸肿"},{"k":"C","t":"手忙：脚乱"},{"k":"D","t":"半斤：八两"}],"answer":"A","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>“心宽体胖”指心情愉快，无所牵挂，因而人感到舒坦，因为“心宽”，所以“体胖”，二者为因果对应关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：“唇亡齿寒”指嘴唇没有了，牙齿就会觉得冷，形容关系密切，利害相关，因为“唇亡”，所以“齿寒”，二者为因果对应关系，与题干逻辑关系一致，当选；<br>B项：“鼻青脸肿”指鼻子青了，脸也肿了，形容面部被碰伤或打伤的样子，也形容遭到严重打击或挫折的狼狈相，二者不是因果对应关系，与题干逻辑关系不一致，排除；<br>C项：“手忙脚乱”形容做事慌张而没有条理，也形容惊慌失措，二者不是因果对应关系，与题干逻辑关系不一致，排除；<br>D项：“半斤八两”比喻彼此一样，不相上下（多含贬义），二者不是因果对应关系，与题干逻辑关系不一致，排除。<br>故正确答案为A。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":53,"pid":"p7e519edba8"},{"qid":"5430385","no":23,"type":"类比推理","module":"判断推理","stem":"<p>长白山：火山</p>","options":[{"k":"A","t":"皇陵：古建筑"},{"k":"B","t":"巢湖：淡水湖"},{"k":"C","t":"连衣裙：丝绸"},{"k":"D","t":"火箭军：军人"}],"answer":"B","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>通常所说的“长白山”指长白山脉主峰，“长白山”是“火山”，且“长白山”是“火山”中的一个，二者为包容关系中的特指。<br>第二步：判断选项词语间逻辑关系。<br>A项：“皇陵”是皇帝或皇室成员的陵墓，“皇陵”是“古建筑”，但“皇陵”是“古建筑”中的一种，二者为包容关系中的种属关系，与题干逻辑关系不一致，排除。<br>B项：“巢湖”是“淡水湖”，且“巢湖”是“淡水湖”中的一个，二者为包容关系中的特指，与题干逻辑关系一致，当选。<br>C项：“丝绸”是制作“连衣裙”的原材料，二者为原材料与成品的对应关系，与题干逻辑关系不一致，排除。<br>D项：“火箭军”是我国解放军的一种，“军人”是“火箭军”的组成部分，二者为组成关系，与题干逻辑关系不一致，排除。<br>故正确答案为B。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":54,"pid":"p7e519edba8"},{"qid":"5430387","no":24,"type":"类比推理","module":"判断推理","stem":"<p>上市公司：跨国企业</p>","options":[{"k":"A","t":"大专院校：高等教育"},{"k":"B","t":"商业银行：金融机构"},{"k":"C","t":"快捷酒店：连锁酒店"},{"k":"D","t":"进口产品：出口产品"}],"answer":"C","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>上市公司指经有关部门核准，公开发行股票并在证券交易所上市交易的股份有限公司。跨国企业指在两个或两个以上国家从事国际化经营活动的企业。有的上市公司是跨国企业，有的上市公司不是跨国企业，有的跨国企业是上市公司，有的跨国企业不是上市公司，二者为交叉关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：高等教育指在完成中等教育的基础上进行的专业教育和职业教育，学历层次包括专科、本科等，因此，大专院校属于高等教育，二者为种属关系，与题干逻辑关系不一致，排除；<br>B项：商业银行是金融机构，二者为种属关系，与题干逻辑关系不一致，排除；<br>C项：快捷酒店是功能简化的经济型酒店的一种，连锁酒店是指连锁经营的酒店，有的快捷酒店是连锁酒店，有的快捷酒店不是连锁酒店，有的连锁酒店是快捷酒店，有的连锁酒店不是快捷酒店，二者为交叉关系，与题干逻辑关系一致，当选；<br>D项：进口产品和出口产品为并列关系，与题干逻辑关系不一致，排除。<br>故正确答案为C。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":55,"pid":"p7e519edba8"},{"qid":"5430389","no":25,"type":"类比推理","module":"判断推理","stem":"<p>蚕茧：丝绸：衣服</p>","options":[{"k":"A","t":"矿山：矿石：螺丝"},{"k":"B","t":"树木：纸张：书本"},{"k":"C","t":"小麦：面条：馒头"},{"k":"D","t":"沙粒：珍珠：项链"}],"answer":"B","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>蚕茧是制作丝绸的原材料，丝绸是制作衣服的原材料，二者均为原材料的对应关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：矿山是产出矿石的地点，二者为地点的对应关系，矿石是制作螺丝的原材料，二者为原材料的对应关系，与题干逻辑关系不一致，排除；<br>B项：树木是制作纸张的原材料，纸张是制作书本的原材料，二者均为原材料的对应关系，与题干逻辑关系一致，当选；<br>C项：小麦是制作面条和馒头的原材料，第一词与后两词分别为原材料的对应关系，且面条和馒头为不同的主食，二者为并列关系，与题干逻辑关系不一致，排除；<br>D项：蚌受到沙粒侵入的刺激会分泌珍珠质将沙粒一层层包裹起来形成珍珠，二者不是原材料的对应关系，与题干逻辑关系不一致，排除。<br>故正确答案为B。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":56,"pid":"p7e519edba8"},{"qid":"5430390","no":26,"type":"类比推理","module":"判断推理","stem":"<p>白天：夜晚：夏夜</p>","options":[{"k":"A","t":"红色：黑色：漆黑"},{"k":"B","t":"中国：外国：欧洲国家"},{"k":"C","t":"高山：大海：南海"},{"k":"D","t":"草原：森林：原始森林"}],"answer":"B","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>除了白天就只有夜晚，二者为并列关系中的矛盾关系，夏夜属于夜晚，二者为种属关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：红色和黑色是两种不同的颜色，除此之外还有其他颜色，二者为并列关系中的反对关系，漆黑属于黑色，二者为种属关系，与题干逻辑关系不一致，排除；<br>B项：除了中国就只有外国，二者为并列关系中的矛盾关系，欧洲国家属于外国，二者为种属关系，与题干逻辑关系一致，当选；<br>C项：高山和大海是两种不同的自然景观，除此之外还有其他自然景观，二者为并列关系中的反对关系，南海属于大海，二者为种属关系，与题干逻辑关系不一致，排除；<br>D项：草原和森林是两种不同的生态系统，除此之外还有其他生态系统，二者为并列关系中的反对关系，原始森林属于森林，二者为种属关系，与题干逻辑关系不一致，排除。<br>故正确答案为B。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":57,"pid":"p7e519edba8"},{"qid":"5430391","no":27,"type":"类比推理","module":"判断推理","stem":"<p>红包：红旗渠：红光满面</p>","options":[{"k":"A","t":"青草：青少年：青红皂白"},{"k":"B","t":"黑夜：黑心肠：黑灯瞎火"},{"k":"C","t":"白雪：白话文：白费心思"},{"k":"D","t":"黄豆：黄包车：黄粱一梦"}],"answer":"D","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>“红包”一词中的“红”指的是红颜色；“红旗渠”得名主要是取“红旗精神”的象征意义，其中“红”指的是红颜色；“红光满面”形容人的气色好，脸色红润，其中“红”指的是红颜色，故三个词中的相同单字“红”的含义相同。<br>第二步：判断选项词语间逻辑关系。<br>A项：“青草”一词中的“青”指的是绿颜色，“青少年”一词中的“青”指的是年轻，两个词中相同单字“青”含义不同，与题干逻辑关系不一致，排除；<br>B项：“黑夜”一词中的“黑”指的是黑颜色，“黑心肠”意思是阴险恶毒的心肠，其中“黑”指的是阴险恶毒，两个词中相同单字“黑”含义不同，与题干逻辑关系不一致，排除；<br>C项：“白雪”一词中的“白”指的是白颜色，“白话文”一词中的“白”指的是直白、通俗易懂，两个词中相同单字“白”含义不同，与题干逻辑关系不一致，排除；<br>D项：“黄豆”一词中的“黄”指的是黄颜色；“黄包车”是人力车，车身涂黄漆，其中“黄”指的是黄颜色；“黄粱一梦”中的黄粱是黄粱米，即小米，其中“黄”指的是黄颜色，故三个词中的相同单字“黄”的含义相同，与题干逻辑关系一致，当选。<br>故正确答案为D。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":58,"pid":"p7e519edba8"},{"qid":"5430392","no":28,"type":"类比推理","module":"判断推理","stem":"<p>售卖假货：举报维权：上门调查</p>","options":[{"k":"A","t":"点菜下单：烹饪菜肴：传送菜品"},{"k":"B","t":"发表文章：勘误声明：印刷错误"},{"k":"C","t":"投递简历：考试通过：正式录取"},{"k":"D","t":"赛前动员：拟定阵容：布置战术"}],"answer":"A","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>首先“售卖假货”，其次“举报维权”，最后“上门调查”，三者为时间先后顺序的对应关系，且“售卖假货”的主体为商家，“举报维权”的主体为消费者，“上门调查”的主体为工商局、质监局，三者主体不一致。<br>第二步：判断选项词语间逻辑关系。<br>A项：首先“点菜下单”，其次“烹饪菜肴”，最后“传送菜品”，三者为时间先后顺序的对应关系，且“点菜下单”的主体为食客，“烹饪菜肴”的主体为厨师，“传送菜品”的主体为服务员，三者主体不一致，与题干逻辑关系一致，当选；<br>B项：首先“发表文章”，其次“印刷错误”，最后“勘误声明”， 三者为时间先后顺序的对应关系，但顺序不一致，与题干逻辑关系不一致，排除；<br>C项：首先“投递简历”，其次“考试通过”，最后“正式录取”，三者为时间先后顺序的对应关系，但“投递简历”与“考试通过”的主体均为应聘者，与题干逻辑关系不一致，排除；<br>D项：首先“赛前动员”，其次“拟定阵容”，最后“布置战术”，三者为时间先后顺序的对应关系，但“赛前动员”“拟定阵容”“布置战术”的主体均为教练，三者主体一致，与题干逻辑关系不一致，排除。<br>故正确答案为A。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":59,"pid":"p7e519edba8"},{"qid":"5430393","no":29,"type":"类比推理","module":"判断推理","stem":"<p>按揭 对于 （    ） 相当于 （    ） 对于 促销</p>","options":[{"k":"A","t":"银行 商场"},{"k":"B","t":"抵押 打折"},{"k":"C","t":"贷款 降价"},{"k":"D","t":"购房 商品"}],"answer":"C","multi":false,"explanation":"<p>A项：在银行办理按揭手续，二者为地点对应关系；在商场进行促销活动，二者为地点对应关系，但逻辑顺序相反，前后逻辑关系不一致，排除；<br>B项：按揭指一种购房或购物的贷款方式，以所购房屋或物品为抵押向银行贷款，然后分期偿还，按揭需要抵押，二者为必要条件对应关系；打折是一种促销方式，二者为种属关系，前后逻辑关系不一致，排除；<br>C项：按揭指一种购房或购物的贷款方式，以所购房屋或物品为抵押向银行贷款，然后分期偿还，按揭是一种贷款方式，二者为种属关系；降价是一种促销方式，二者为种属关系，前后逻辑关系一致，当选；<br>D项：按揭指一种购房或购物的贷款方式，以所购房屋或物品为抵押向银行贷款，然后分期偿还，按揭是购房的一种方式，二者为方式目的对应关系；对商品进行促销，商品是进行促销的对象，前后逻辑关系不一致，排除。<br>故正确答案为C。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":60,"pid":"p7e519edba8"},{"qid":"5430394","no":30,"type":"类比推理","module":"判断推理","stem":"<p>（    ） 对于 音乐 相当于 真相 对于 （    ）</p>","options":[{"k":"A","t":"演奏 揭露"},{"k":"B","t":"感动 激愤"},{"k":"C","t":"浪漫 报纸"},{"k":"D","t":"旋律 新闻"}],"answer":"D","multi":false,"explanation":"<p>A项：演奏音乐，二者为动宾结构；揭露真相，二者为动宾结构，但词语先后顺序相反，前后逻辑关系不一致，排除；<br>B项：令人感动的音乐，感动可以用来修饰音乐，二者为偏正关系；令人激愤的真相，激愤可以用来修饰真相，二者为偏正关系，但词语先后顺序相反，前后逻辑关系不一致，排除；<br>C项：浪漫的音乐，浪漫可以用来修饰音乐，二者为偏正关系；在报纸上揭露真相，报纸是真相的载体，前后逻辑关系不一致，排除；<br>D项：旋律是音乐的一部分，二者为组成关系；新闻包含了真相，二者为组成关系，前后逻辑关系一致，当选。<br>故正确答案为D。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":61,"pid":"p7e519edba8"},{"qid":"5430352","no":31,"type":"类比推理","module":"判断推理","stem":"<p>小明、小军、小花、小飞和小雅在学校的联欢会上表演节目，表演时他们每人手上各拿了一个不同的气球，气球分别是红色圆形、蓝色五角星形、黄色心形、蓝色圆形、红色心形。<br>小明说：小花和小雅的气球都不是圆形的，也不是蓝色的。<br>小军说：我的气球与小雅的颜色和形状都不一样。<br>小飞说：小雅的气球是黄色的，小明的气球是蓝色的。<br>小花说：小军的气球与我的是一样的颜色，小飞的气球不是五角星形的。<br>根据以上信息，下列说法正确的是：</p>","options":[{"k":"A","t":"小军的气球是红色心形的"},{"k":"B","t":"小花的气球是黄色心形的"},{"k":"C","t":"小飞的气球是红色圆形的"},{"k":"D","t":"小明的气球是蓝色五角星形的"}],"answer":"D","multi":false,"explanation":"<p>第一步：整理题干条件。<br>①气球分别是红色圆形、蓝色五角星形、黄色心形、蓝色圆形、红色心形；<br>②小花和小雅的气球不是圆形的，也不是蓝色的；<br>③小军与小雅的气球颜色和形状都不一样；<br>④小雅的气球是黄色的，小明的气球是蓝色的；<br>⑤小军与小花的气球颜色一样，小飞的气球不是五角星形的。<br>第二步：根据题干条件进行推理。<br>由于对象和信息较多，可以考虑从提到次数最多的“小雅”开始推理。根据条件①②④可知，小雅的气球是黄色心形的，小花的气球是红色心形的。再根据条件⑤可知，小军与小花的气球颜色一样，那么小军的气球是红色圆形的，且小飞的气球不是五角星形的，那么小飞的气球是蓝色圆形的，故小明的气球是蓝色五角星形的。<br>故正确答案为D。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":62,"pid":"p7e519edba8"},{"qid":"5430353","no":32,"type":"逻辑判断","module":"判断推理","stem":"<p>关于小张、小李书法学习的情况，有如下判断：（1）如果小张学习魏碑，那么小李学习汉隶；（2）小张既没有学习秦篆，也没有学习魏碑；（3）小张或者学习秦篆，或者学习魏碑。结果发现，上述判断有两项是错误的。<br>根据以上信息，可以得出以下哪项结论？</p>","options":[{"k":"A","t":"小张学习魏碑，小李学习汉隶"},{"k":"B","t":"小张没有学习魏碑，小李学习汉隶"},{"k":"C","t":"小张学习魏碑，小李没有学习汉隶"},{"k":"D","t":"小张没有学习魏碑，小李没有学习汉隶"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出题干矛盾命题。</p><p>（1）小张学习魏碑<img src=\"assets/img/gongshi/formula-af79ef1caa883905.png\" class=\"tex\">小李学习汉隶；</p><p>（2）<img src=\"assets/img/gongshi/formula-7ab67fb9ad7cdd2c.png\" class=\"tex\">小张学习秦篆 且 <img src=\"assets/img/gongshi/formula-7ab67fb9ad7cdd2c.png\" class=\"tex\">小张学习魏碑；</p><p>（3）小张学习秦篆 或 小张学习魏碑。</p><p>分析题干条件，（2）与（3）为矛盾关系，必有一真一假。</p><p>第二步：根据题干条件进行推理。</p><p>根据题干条件可知，3个条件中有2个是错误的，故（1）一定错误，因此其矛盾命题“小张学习魏碑 且 <img src=\"assets/img/gongshi/formula-7ab67fb9ad7cdd2c.png\" class=\"tex\">小李学习汉隶”一定为真，即小张学习魏碑，小李没有学习汉隶，对应C项。</p><p>故正确答案为C。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":63,"pid":"p7e519edba8"},{"qid":"5430355","no":33,"type":"逻辑判断","module":"判断推理","stem":"<p>某地区中小学教师中，毕业于师范类院校的女教师多于毕业于非师范类院校的男教师，<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，所以，该地区中小学女教师比男教师多。<br>要使上述推理成立，最适合填入画横线位置的是：</p>","options":[{"k":"A","t":"毕业于师范类院校的教师少于毕业于非师范类院校的教师"},{"k":"B","t":"毕业于师范类院校的教师多于毕业于非师范类院校的教师"},{"k":"C","t":"毕业于师范类院校的女教师比毕业于非师范类院校的男教师多"},{"k":"D","t":"毕业于非师范类院校的女教师比毕业于非师范类院校的男教师多"}],"answer":"A","multi":false,"explanation":"<p>第一步：分析题干条件。<br>（1）师范类（女）＞非师范类（男）。<br>第二步：根据题干条件进行推理。<br>本题提问方式类似于“补充以下哪项条件”，可以考虑代入法。<br>代入A项：师范类（男+女）＜非师范类（男+女），即（2）师范类（男）+师范类（女）＜非师范类（男）+非师范类（女），结合条件（1）可以得到：（3）师范类（男）＜非师范类（女），此时（1）+（3）可以得到：女（师范类+非师范类）＞男（师范类+非师范类），可以得到“该地区中小学女教师比男教师多”的结论，当选；<br>代入B项：师范类（男+女）＞非师范类（男+女），即（2）师范类（男）+师范类（女）＞非师范类（男）+非师范类（女），结合条件（1）无法得到“该地区中小学女教师比男教师多”的结论，排除；<br>代入C项：师范类（女）＞非师范类（男），与条件（1）相同，无法得到“该地区中小学女教师比男教师多”的结论，排除；<br>代入D项：非师范类（女）＞非师范类（男），结合条件（1）无法得到“该地区中小学女教师比男教师多”的结论，排除。<br>故正确答案为A。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":64,"pid":"p7e519edba8"},{"qid":"5430357","no":34,"type":"逻辑判断","module":"判断推理","stem":"<p>一项研究通过比较某市在参与创建全国卫生城市前后的环境空气质量发现，该市在参与创建全国卫生城市之后环境空气质量明显优于之前，因此该研究得出结论，创建全国卫生城市有助于提升该市的环境空气质量。<br>以下哪项如果为真，最能支持上述结论？</p>","options":[{"k":"A","t":"参与全国卫生城市创建能够获得更多的政府专项财政补助"},{"k":"B","t":"众多城市考察团常常来该市学习创建全国卫生城市的经验"},{"k":"C","t":"参与全国卫生城市创建之前，该市环境空气质量长期处于较差的状况"},{"k":"D","t":"周边未参与全国卫生城市创建的城市在同时期环境空气质量有所下降"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：创建全国卫生城市有助于提升该市的环境空气质量。<br>论据：一项研究通过比较某市在参与创建全国卫生城市前后的环境空气质量发现，该市在参与创建全国卫生城市之后环境空气质量明显优于之前。<br>本题论点论据均在讨论创建全国卫生城市与该市环境空气质量提升之间的关系，论点论据话题一致，加强优先考虑补充论据。<br>第二步：逐一分析选项。<br>A项：该项讨论的是参与全国卫生城市创建能获得更多的财政补助，而论点讨论的是参加全国卫生城市创建可以提升环境空气质量，话题不一致，无法加强，排除；<br>B项：该项讨论的是其他城市常常学习该市创建全国卫生城市的经验，只能说明该市的环境空气质量优于其他城市，而论点比较的是该市创建全国卫生城市前后的环境空气质量，是自己与自己进行比较，话题不一致，无法加强，排除；<br>C项：该项指出参与全国卫生城市创建之前，该市的环境空气质量较差，说明该市在参与创建全国卫生城市之后环境空气质量确实更优，补充了论据，可以加强，当选；<br>D项：该项说的是未参与全国卫生城市创建的城市的情况，而题干讨论的是该市的情况，主体不一致，无法加强，排除。<br>本题出得不是特别好，如果论点不是有助于提升“该市”的空气质量，而是有助于提升空气质量，那么D项补充对比论据是可以加强的，但是论点现在强调的是“该市”，D项说“其他城市”的情况，此类选项就没那么好了，故择优给到还是在说“该市”的C项。<br>故正确答案为C。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":65,"pid":"p7e519edba8"},{"qid":"5430359","no":35,"type":"逻辑判断","module":"判断推理","stem":"<p>一直以来，高楼大厦被视为城市的象征，甚至很多地方以建筑高度作为城市现代化的象征。越来越多的摩天大楼拔地而起，竞相突破城市天际线的纪录。根据我国《民用建筑设计统一标准》，建筑高度大于100米的即为超高层建筑。这些摩天大楼虽然看起来“挺拔壮观”，但背后的隐患不容忽视。因此，“限高”势在必行。<br>以下哪项如果为真，最能支持上述观点？</p>","options":[{"k":"A","t":"超高层建筑工程造价和运维成本更高，建造施工难度更大"},{"k":"B","t":"中国150米、200米、300米以上建筑的数量均保持全球第一"},{"k":"C","t":"超高层建筑安全风险更大，逃生疏散时间长，消防设施、抗震技术复杂，管理运维要求更高"},{"k":"D","t":"城市建筑风貌是城市外在形象和内质精神的有机统一，限高有利于打造更多符合城市风貌的建筑"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：“限高”势在必行。<br>论据：根据我国《民用建筑设计统一标准》，建筑高度大于100米的即为超高层建筑。这些摩天大楼虽然看起来“挺拔壮观”，但背后的隐患不容忽视。<br>本题的论点讨论的是“限高”势在必行，论据讨论的是摩天大楼背后的隐患不容忽视，可以合理推出需要“限高”，可以看作论点论据话题一致，加强优先考虑补充论据。<br>第二步：逐一分析选项。<br>A项：该项讨论的是超高层建筑工程造价和运维成本更高，施工难度更大，并没有提及它有什么隐患，进而也无法证明这些摩天大楼是否需要“限高”，话题不一致，无法加强，排除；<br>B项：该项讨论的是中国的超高层建筑的数量在全球保持第一，而论点讨论的是这些高层建筑背后的隐患，话题不一致，无法加强，排除；<br>C项：该项指出超高层建筑安全风险更大，并解释说明了这些超高层建筑确实具有安全隐患，应该“限高”，补充论据，可以加强，当选；<br>D项：该项指出限高有利于打造更多符合城市风貌的建筑，而论点讨论的是超高建筑因为有安全隐患所以需要限高，话题不一致，无法加强，排除。<br>故正确答案为C。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":66,"pid":"p7e519edba8"},{"qid":"5430364","no":36,"type":"图形推理","module":"判断推理","stem":"<p>在戏剧史上，从三棱景柱的出现到立体布景的使用，从煤气灯照明到电脑灯的布控，都曾使戏剧演出的总体面貌产生巨大变化。剧场科技、智能舞台、多媒体、声学、光学、电学技术的广泛运用，丰富了当代舞台的表现手段和艺术面貌，并且为人们带来全新的审美体验。有文化学者据此推断，戏剧艺术对现代科技手段会越来越倚重，演员不主动适应被各种科技元素构筑起来的表演空间，就会被时代所淘汰。<br>以下哪项如果为真，最能削弱该学者的推断？</p>","options":[{"k":"A","t":"借助现代拍摄技术和传播手段，国家大剧院的演出可以实时传播到世界各地"},{"k":"B","t":"中国传统戏曲“一桌二椅”的高度象征性和程式化表演方式，更有独特的艺术魅力"},{"k":"C","t":"剧场科技、智能舞台等现代科技手段的广泛运用，没有实质性改变戏剧的艺术面貌"},{"k":"D","t":"一些演员依赖现代科技手段替代有可能损伤身体的传统危险表演动作，降低了艺术魅力"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：戏剧艺术对现代科技手段会越来越倚重，演员不主动适应被各种科技元素构筑起来的表演空间，就会被时代所淘汰。<br>论据：剧场科技、智能舞台、多媒体、声学、光学、电学技术的广泛运用，丰富了当代舞台的表现手段和艺术面貌，并且为人们带来全新的审美体验。<br>本题论点讨论的是演员不主动适应被各种科技元素构筑起来的表演空间，就会被时代所淘汰，论据讨论的是各种科技元素丰富了舞台，且为人们带来全新的审美体验。论点论据都在讨论加入科技元素的戏剧艺术，论点和论据话题一致，削弱优先考虑削弱论点。<br>第二步：逐一分析选项。<br>A项：该项讨论的是现代拍摄技术和传播手段有利于演出的传播，但是论点讨论的是如果演员不主动适应被各种科技元素构筑起来的表演空间，是否会被时代所淘汰，话题不一致，无法削弱，排除；<br>B项：该项讨论的是中国传统戏曲“一桌二椅”更有独特的艺术魅力，通过举例子表明传统的戏剧艺术具有独特魅力，那么就有可能不会被现代科技手段所取代，不会被时代所淘汰，具有一定的削弱力度，保留；<br>C项：该项指出现代科技手段的广泛运用没有实质性改变戏剧的艺术面貌，指出艺术的表现形式不是最重要的，艺术本身更为关键，而科技不会改变艺术本身，那么即使演员不主动适应各种科技元素，也不会被时代淘汰，直接否定论点，保留；<br>D项：该项指出加入现代科技手段后，降低了艺术魅力，讨论的是艺术魅力的高低，但是论点讨论的是如果演员不主动适应被各种科技元素构筑起来的表演空间，是否会被时代所淘汰，话题不一致，无法削弱，排除。<br>对比BC两项，第一，B项举出“一桌二椅”的个例，而C项从整体进行论证，整体大于部分，C项更优；第二，对比关键词，B项的例子题干并未涉及，而C项的“剧场科技、智能舞台等现代科技手段”正是题干讨论的内容，C项的关键词更贴近题干。综上，对比择优，本题答案择优为C项。<br>故正确答案为C。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":67,"pid":"p7e519edba8"},{"qid":"5430367","no":37,"type":"逻辑判断","module":"判断推理","stem":"<p>研究人员开发了一种可以从指尖上的汗水中获取能量的新设备。在10小时的睡眠期间内，无需任何机械能量输入的情况下，该设备每平方厘米可产生300毫焦耳的能量；只需按一下手指，就能额外产生30毫焦耳的能量。这意味着可自我维持的可穿戴电子产品向更实用、更方便、更大众化的方向迈出了重要一步。<br>以下哪项如果为真，最能支持上述论述？</p>","options":[{"k":"A","t":"新设备产生的电能可被储存在小电容器中，并在需要时释放到其他设备"},{"k":"B","t":"此前基于汗水收集能量的设备需要佩戴者大量运动出足够的汗来激活发电"},{"k":"C","t":"手指是身体24小时的“汗水工厂”，产生的汗量是其他部位的100到1000倍"},{"k":"D","t":"一名受试者在10小时睡眠中收集了近400毫焦耳的能量，这足以为一块电子表提供24小时电力"}],"answer":"B","multi":false,"explanation":"<p>第一步：找出论点和论据。</p><p>论点：可自我维持的可穿戴电子产品向更实用、更方便、更大众化的方向迈出了重要一步。</p><p>论据：在10小时的睡眠期间内，无需任何机械能量输入的情况下，该设备每平方厘米可产生300毫焦耳的能量；只需按一下手指，就能额外产生30毫焦耳的能量。</p><p>论据讨论的是睡眠期间可通过手指让新设备产生能量，论点说的是新设备的出现意味着可自我维持的可穿戴电子产品变得更实用、更方便、更大众化了，论据和论点的话题一致，加强优先考虑补充论据。</p><p>第二步：逐一分析选项。</p><p>A项：选项指出新设备产生的电能可以被储存并能释放到其他设备，但论点说的是新设备的出现意味着可自我维持的可穿戴电子产品变得更实用、更方便、更大众化了，话题不一致，为无关项，无法加强，排除；</p><p>B项：选项指出此前的设备需要大量出汗激活发电，而现有论据表明现在的设备只需要指尖上的少量汗水即可激活，说明可穿戴电子产品确实向更实用、更方便、更大众化的方向发展了，补充论据，可以加强，保留；</p><p>C项：选项指出手指产生的汗量比其他部位高，但是没有提及手指产生的汗是否能转化成能量，进而让这个设备更便携，为不明确项，无法加强，排除；</p><p>D项：选项举了一名受试者的例子证明该新设备确实可以在人们睡眠期间产生能量，补充论据，可以加强，保留。</p><p>对比B、D两项，本题论点中存在现在和以前设备之间的比较关系，B项补充了此前设备的情况，D项虽然举了一个例子但仍然在表述当前设备的情况，因此择优选择B项。注：B选项属于原文中的论述原话，用于说明可穿戴电子产品确实向更实用、更方便、更大众化的方向发展了，如下图所示。</p><p><img src=\"assets/img/timu/185aa04a84b66ad.jpg\" class=\"fig\" style=\"width:406px;height:449px;\"></p><p> 故正确答案为B。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":68,"pid":"p7e519edba8"},{"qid":"5430369","no":38,"type":"逻辑判断","module":"判断推理","stem":"<p>某考古小组对发生于两千多年前维苏威火山爆发的300多名成年罗马人遗体骨骼中的氨基酸的碳和氨进行同位素分析后发现，其中的男性从海鲜中获得的蛋白质要比女性多50%。与之相对应，其中的女性的蛋白质来源主要依赖肉、蛋、奶等动物产品和当地出产的豆类与坚果。<br>以下哪项如果为真，最能解释这一发现？</p>","options":[{"k":"A","t":"相比于动物产品、豆类和坚果，海鲜中的蛋白质含量更高"},{"k":"B","t":"当时罗马男性更多从事渔业和海洋活动，摄入食物以海鲜为主"},{"k":"C","t":"两千多年前的罗马人饮食习惯与现在的饮食习惯没有很大差异"},{"k":"D","t":"男性对海鲜中蛋白质的吸收能力比对其他动物、豆类、坚果更高"}],"answer":"B","multi":false,"explanation":"<p>第一步：找出题干矛盾。<br>男性从海鲜中获得的蛋白质要比女性多50%。与之相对应，其中的女性的蛋白质来源主要依赖肉、蛋、奶等动物产品和当地出产的豆类与坚果。<br>第二步：逐一分析选项。<br>A项：只说了海鲜的蛋白质含量比动物产品、豆类和坚果高，但是没有提及为何男性与女性之间获得蛋白质的主要食物来源不同，不能解释题干矛盾，排除；<br>B项：说明当时罗马男性的主要食物为海鲜，解释了为何当时罗马男性与女性相比，从海鲜中获得的蛋白质较高，可以解释题干矛盾，当选；<br>C项：当时的罗马人饮食习惯与现在相似，但是没有提及为何当时罗马男性与女性获得蛋白质的主要食物来源不同，不能解释题干矛盾，排除；<br>D项：男性对海鲜中蛋白质的吸收能力较高，但是没有提及女性对海鲜中蛋白质的吸收能力和当时罗马男性的主要食物来源是否为海鲜，不能解释题干矛盾，排除。<br>故正确答案为B。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":69,"pid":"p7e519edba8"},{"qid":"5430371","no":39,"type":"逻辑判断","module":"判断推理","stem":"<p>三叠纪末期中央大西洋超级火成岩省喷发造成的火山冬天导致大量陆地生物灭绝，恐龙却避过了这一灾难，并于三叠纪末生物灭绝事件后迅速占据生态主位。恐龙为什么能在生物灭绝的天灾中得以生存，并于灾后蓬勃发展？晚三叠世至早侏罗世早期是地球历史上典型的温室时期，地球两极不存在冰川，森林覆盖到达潘吉亚大陆的南北两极。研究人员在潘吉亚大陆的北极地区准噶尔盆地晚三叠世至早侏罗世湖沼相泥岩中发现了保存精美的恐龙脚印化石，据此认为早已适应极地寒冷的气候是恐龙崛起的主要原因。<br>下列哪项最可能是研究人员得出结论的条件？</p>","options":[{"k":"A","t":"晚三叠世至早侏罗世早期恐龙生活于极地地区"},{"k":"B","t":"大灭绝事件后恐龙体积迅速增加，地理分布范围迅速扩张"},{"k":"C","t":"即使两极无冰川的温室地球时期，极地也存在季节性的结冰"},{"k":"D","t":"在大灭绝中幸存下来的大多是分布于中、高纬度地区的恐龙"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出论点和论据。</p><p>论点：早已适应极地寒冷的气候是恐龙崛起的主要原因。</p><p>论据：研究人员在潘吉亚大陆的北极地区准噶尔盆地晚三叠世至早侏罗世湖沼相泥岩中发现了保存精美的恐龙脚印化石。</p><p>本题论据说的是研究人员在晚三叠世至早侏罗世的北极地区发现了恐龙脚印化石，说明在该时期确实有恐龙生活在北极地区，而论点讨论的是恐龙崛起与寒冷气候之间的关系，二者话题不一致，加强优先考虑搭桥，即建立“北极地区”和“寒冷气候”之间的联系。</p><p>第二步：逐一分析选项。</p><p>A项：该项指出晚三叠世至早侏罗世早期确实有恐龙生活在极地地区，补充论据，可以加强，保留；</p><p>B项：该项指出大灭绝事件后恐龙的体积及其分布地区的变化情况，而论点讨论的是恐龙崛起与寒冷气候之间的关系，话题不一致，无法加强，排除；</p><p>C项：该项指出即使在两极无冰川的温室地球时期，极地也存在季节性的结冰，说明该时期北极地区的气候也会出现季节性的寒冷，建立了“北极地区”和“寒冷气候”之间的联系，为搭桥项，可以加强，保留；</p><p>D项：该项讨论的是在大灭绝中幸存下来的恐龙的具体分布位置，而论点讨论的是恐龙崛起与寒冷气候之间的关系，这些幸存的恐龙当时所处的位置是否寒冷并不确定，为不明确项，无法加强，排除。</p><p>对比A、C两项，A项为补充论据，C项为搭桥，搭桥的力度大于补充论据，C项当选。</p><p>故正确答案为C。</p><p>https://baijiahao.baidu.com/s?id=1737217080173007095&amp;wfr=spider&amp;for=pc（涉及题干、A项和C项，A项恐龙确实生活在北极地区是可以通过论据中的脚印直接推测出的，A项并没有讨论恐龙是否已经适应严寒，而C项讨论了恐龙是否已适应严寒，与论点话题更为一致。）</p><p><img src=\"assets/img/timu/1852a17451e8ad6.png\" class=\"fig\" style=\"width:700px;height:293px;\"></p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":70,"pid":"p7e519edba8"},{"qid":"5430373","no":40,"type":"逻辑判断","module":"判断推理","stem":"<p>许多心理学家将工作记忆描述为“当你遇到其他信息或任务干扰时，继续记住一定信息的能力”。工作记忆是大脑中负责储存和处理信息，进行决策跟计划的部分。它决定了短时记忆和长时记忆中能储存、处理多少信息，还决定了这些信息的注意控制、质量和数量。工作记忆较差的人很难将注意力分给不同的信息片段，导致他们难以高效处理多重任务——尤其是当他们遇到完全陌生的话题时。因此，工作记忆在多任务处理中扮演着重要的角色。<br>以下哪项如果为真，最能支持上述结论？</p>","options":[{"k":"A","t":"噪音等外界干扰会降低人们处理多任务的能力"},{"k":"B","t":"老年人或出现认知障碍的人的工作记忆会有所衰退"},{"k":"C","t":"工作记忆并非一成不变，可以通过练习和训练得以加强"},{"k":"D","t":"工作记忆强的人能轻松地在不同内容的网页间切换并成功找到所要的结果"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：工作记忆在多任务处理中扮演着重要的角色。<br>论据：工作记忆较差的人很难将注意力分给不同的信息片段，导致他们难以高效处理多重任务——尤其是当他们遇到完全陌生的话题时。<br>论点和论据讨论的都是工作记忆与多任务处理之间的关系，二者话题一致，加强优先考虑补充论据。<br>第二步：逐一分析选项。<br>A项：该项指出噪音等外界干扰会降低人们处理多任务的能力，讨论的是外界干扰与多任务处理之间的关系，而论点讨论的是工作记忆对多任务处理是否有影响，二者讨论的话题不一致，为无关项，无法加强，排除；<br>B项：该项指出老年人或出现认知障碍的人的工作记忆会有所衰退，讨论的是哪些因素会影响工作记忆，而论点讨论的是工作记忆对多任务处理是否有影响，二者讨论的话题不一致，为无关项，无法加强，排除；<br>C项：该项指出通过练习和训练可以加强工作记忆，讨论的是哪些因素会影响工作记忆，而论点讨论的是工作记忆对多任务处理是否有影响，二者讨论的话题不一致，为无关项，无法加强，排除；<br>D项：该项指出工作记忆强的人面对繁多的网页内容也能成功找到结果，通过举例的方式证明了工作记忆确实可以在多任务处理中发挥重要作用，补充论据，可以加强，当选。<br>故正确答案为D。</p>","from":{"file":"2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版）.md","module":"判断推理"},"idx":71,"pid":"p7e519edba8"}]};
